  if (page === 'agenda') return '/agenda' + _optSuffix(() => agendaMode === 'team' ? '/team' : agendaWeeks === 1 ? '/week' : '/two-weeks');
  if (page === 'profile') return '/profile' + _optSuffix(() => _profileSection !== 'account' ? '/' + _profileSection : '');
