function emptyState(title, sub, iconName, cta) {
  const icon = EMPTY_ICONS[iconName] || EMPTY_ICONS.default;
  // cta opcional: { label, onclick, icon?, variant? ('primary' default | 'ghost') }
  const ctaHtml = cta && cta.label
    ? `<button type="button" class="empty-state-cta ${cta.variant === 'ghost' ? 'is-ghost' : ''}" onclick="${cta.onclick}">
        ${cta.icon ? `<i data-lucide="${cta.icon}" class="ic-sm"></i>` : ''}
        <span>${esc(cta.label)}</span>
      </button>`
    : '';
  return `<div class="empty-state">
    <div class="empty-state-icon">${icon}</div>
    <div class="empty-state-title">${esc(title)}</div>
    <div class="empty-state-sub">${esc(sub || '')}</div>
    ${ctaHtml}
  </div>`;
}

/* Mini empty state pra cantos pequenos (widgets, colunas, tabelas de modal) onde
   a ilustração 200×150 do emptyState() seria grande demais. Ícone inline (sem
   depender de paintIcons) + texto centrado e discreto. */
function emptyMini(text) {
  return `<div class="empty-mini">
    <svg class="empty-mini-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 13h3l2 3h6l2-3h3"/><path d="M5.4 6.7 4 13v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4l-1.4-6.3a1 1 0 0 0-1-.8H6.4a1 1 0 0 0-1 .8Z"/></svg>
    <span>${esc(text)}</span>
  </div>`;
}

/* ─── KPI TILES (reutilizável) ───
   items = [{ label, value, sub?, tone?, icon? }]
   tone: 'default'|'accent'|'danger'|'success'|'warn' — colore ícone + número. */
function kpiTiles(items) {
  return items.map(k => `
    <div class="kpi-tile ${k.tone ? 'kpi-tile--' + k.tone : ''}">
      ${k.icon ? `<div class="kpi-tile-icon"><i data-lucide="${k.icon}" class="ic-sm"></i></div>` : ''}
      <div class="kpi-tile-body">
        <div class="kpi-tile-value">${esc(String(k.value))}</div>
        <div class="kpi-tile-label">${esc(k.label)}</div>
        ${k.sub ? `<div class="kpi-tile-sub">${esc(k.sub)}</div>` : ''}
      </div>
    </div>`).join('');
}

/* ─── DONUT SVG (reutilizável) ───
   segments = [{ value, color, label }]; opts = { size, thickness, centerValue, centerSub }.
   Arcos via stroke-dasharray; o grupo é rotacionado -90° pra começar no topo,
   mantendo o texto central na horizontal. */
function donutSVG(segments, opts = {}) {
  const size = opts.size || 128;
  const thick = opts.thickness || 15;
  const r = (size - thick) / 2;
  const cx = size / 2, cy = size / 2;
  const C = 2 * Math.PI * r;
  const total = segments.reduce((s, x) => s + (x.value || 0), 0);
  let acc = 0;
  const arcs = total > 0 ? segments.filter(s => s.value > 0).map((s, i) => {
    const frac = s.value / total;
    const len = frac * C;
    const off = -acc * C;
    acc += frac;
    // Anima a stroke-dasharray via CSS var + keyframes — cada slice entra em
    // sequência (stagger 120ms). Fica "preenchendo" em vez de aparecer pronto.
    return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${s.color}" stroke-width="${thick}" stroke-linecap="butt" class="donut-slice" style="--slice-len:${len.toFixed(2)};--slice-gap:${(C - len).toFixed(2)};--slice-off:${off.toFixed(2)};--slice-delay:${i * 120}ms"/>`;
  }).join('') : '';
  const track = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--hairline)" stroke-width="${thick}"/>`;
  const hasSub = !!opts.centerSub;
  // Com sublabel, sobe o número e desce o label pra abrir espaço entre os dois,
  // mantendo o par centrado no anel.
  const valY = hasSub ? cy - 9 : cy;
  const center = (opts.centerValue !== undefined)
    ? `<text x="${cx}" y="${valY}" text-anchor="middle" dominant-baseline="central" class="donut-center-value">${esc(String(opts.centerValue))}</text>
       ${hasSub ? `<text x="${cx}" y="${cy + 17}" text-anchor="middle" class="donut-center-sub">${esc(opts.centerSub)}</text>` : ''}`
    : '';
  return `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" class="donut-svg">
    <g transform="rotate(-90 ${cx} ${cy})">${track}${arcs}</g>
    ${center}
  </svg>`;
}

/* Preenche uma faixa de KPI tiles no detalhe de Cliente/Projeto a partir das
   demandas dos projectIds informados (em aberto / atrasadas / vencem em breve /
   entregues no mês). Reutilizado pelos dois detalhes. */
function renderDetailKpis(elId, projectIds) {
  const el = $(elId); if (!el) return;
  const ids = new Set(projectIds);
  const ds = (demands || []).filter(d => !d.deletedAt && ids.has(d.projectId));
  const open = ds.filter(d => !isDone(d));
  const late = open.filter(isLate);
  const soon = open.filter(d => { const u = dueUrgency(d); return u === 'today' || u === 'soon'; });
  const ymNow = new Date().toISOString().slice(0, 7);
  const doneMonth = ds.filter(d => d.completedAt && d.completedAt.slice(0, 7) === ymNow);
  el.innerHTML = kpiTiles([
    { label: 'em aberto', value: open.length, icon: 'layers', tone: 'accent' },
    { label: 'atrasadas', value: late.length, icon: 'alert-triangle', tone: late.length ? 'danger' : 'default' },
    { label: 'vencem em 2d', value: soon.length, icon: 'clock', tone: soon.length ? 'warn' : 'default' },
    { label: 'entregues no mês', value: doneMonth.length, icon: 'check-circle-2', tone: 'success' },
  ]);
  paintIcons();
}

// ─── SKELETONS ───
function skeletonMetrics(n = 4) {
  return Array.from({length: n}, () => `
    <div class="metric-card">
      <div class="skeleton skeleton-line sm" style="width:55%;margin-bottom:14px"></div>
      <div class="skeleton skeleton-line lg" style="width:42%;margin-bottom:10px"></div>
      <div class="skeleton skeleton-line xs" style="width:70%"></div>
    </div>`).join('');
}
function skeletonTableRows(cols = 7, rows = 6) {
  return Array.from({length: rows}, (_, i) => `
    <tr><td colspan="${cols}"><div class="skeleton skeleton-line" style="width:${50 + ((i * 13) % 40)}%;margin:0"></div></td></tr>
  `).join('');
}

/* ─── HOVER TOOLTIP PARA GRÁFICOS DE LINHA ──────────────────────
   Genérico: recebe um host (com SVG dentro, preserveAspectRatio="none"
   recomendado) e config com pontos no sistema de coordenadas do viewBox.
   Mostra: tooltip flutuante + linha-guia vertical + ponto destacado.

   config = {
     viewBox:  { w, h, padL, padR, padT, innerH },
     points:   [ { x, label, series: [{ y, value, color }] } ],
     lineEls:  HTMLElement (guide line dentro do SVG) — opcional
     markerEls:[HTMLElement] (1 por série, dentro do SVG) — opcional
     tooltipEl:HTMLElement absoluta dentro do host
     format:   (val, seriesIdx) => string
   } */
function attachChartHover(host, config) {
  if (!host || !config.points || !config.points.length) return;
  const tip = config.tooltipEl;
  const guide = config.lineEls;
  const markers = config.markerEls || [];
  const { w: vbW, h: vbH, padT, innerH } = config.viewBox;
  let lastIdx = -1;

  const onMove = (e) => {
    const rect = host.getBoundingClientRect();
    if (!rect.width) return;
    const localX = e.clientX - rect.left;
    const svgX = localX * vbW / rect.width;
    // Acha o ponto mais próximo
    let best = 0, bestDist = Infinity;
    for (let i = 0; i < config.points.length; i++) {
      const d = Math.abs(config.points[i].x - svgX);
      if (d < bestDist) { bestDist = d; best = i; }
    }
    if (best === lastIdx) return;
    lastIdx = best;
    const p = config.points[best];
    // Posiciona guide line + markers (em SVG coords)
    if (guide) {
      guide.setAttribute('x1', p.x);
      guide.setAttribute('x2', p.x);
      guide.style.opacity = '1';
    }
    p.series.forEach((s, i) => {
      const m = markers[i];
      if (!m) return;
      m.setAttribute('cx', p.x);
      m.setAttribute('cy', s.y);
      m.style.opacity = '1';
    });
    // Posiciona tooltip (em pixel coords do host)
    if (tip) {
      const lines = p.series.map((s, i) => {
        const sw = s.color ? `<span class="chart-tip-dot" style="background:${s.color}"></span>` : '';
        return `<div class="chart-tip-row">${sw}<span class="chart-tip-label">${esc(s.name || '')}</span><span class="chart-tip-value">${esc(config.format(s.value, i))}</span></div>`;
      }).join('');
      tip.innerHTML = `<div class="chart-tip-head">${esc(p.label)}</div>${lines}`;
      const tipX = p.x * rect.width / vbW;
      // Limita pra não vazar o host
      const tipW = tip.offsetWidth || 140;
      let left = tipX + 10;
      if (left + tipW > rect.width - 8) left = tipX - tipW - 10;
      if (left < 4) left = 4;
      tip.style.left = left + 'px';
      tip.style.top = '8px';
      tip.style.opacity = '1';
    }
  };
  const onLeave = () => {
    lastIdx = -1;
    if (tip) tip.style.opacity = '0';
    if (guide) guide.style.opacity = '0';
    markers.forEach(m => m && (m.style.opacity = '0'));
  };
  host.addEventListener('mousemove', onMove);
  host.addEventListener('mouseleave', onLeave);
}

// ─── SPARKLINE (mini SVG line chart) ───
function sparkline(values, opts = {}) {
  if (!Array.isArray(values) || values.length < 2) return '';
  const w = opts.width || 96;
  const h = opts.height || 24;
  const color = opts.color || 'var(--accent-text)';
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const step = w / (values.length - 1);
  const pad = 2;
  const pts = values.map((v, i) => {
    const x = i * step;
    const y = h - pad - ((v - min) / range) * (h - pad * 2);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const lastY = h - pad - ((values[values.length - 1] - min) / range) * (h - pad * 2);
  const lastX = (values.length - 1) * step;
  const areaPath = `M0,${h} L${pts.join(' L')} L${w},${h} Z`;
  const linePath = `M${pts.join(' L')}`;
  const gid = 'spk' + Math.random().toString(36).slice(2, 8);
  return `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" preserveAspectRatio="none" style="display:block;overflow:visible">
    <defs><linearGradient id="${gid}" x1="0" x2="0" y1="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.32"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    <path d="${areaPath}" fill="url(#${gid})"/>
    <path d="${linePath}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" opacity="0.9"/>
    <circle cx="${lastX.toFixed(1)}" cy="${lastY.toFixed(1)}" r="2" fill="${color}"/>
  </svg>`;
}

/* Toast com botão "Desfazer" — usado após soft delete de demanda/cliente/projeto.
   `undoFn` só é chamado se o usuário clicar antes do toast desaparecer (~8s).
   Depois disso o item continua recuperável na Lixeira por 30 dias, quando o
   backend faz o purge definitivo (config em UNDO_PURGE_MS). */
function toastWithUndo(msg, undoFn) {
  toast(msg, 'warn', {
    label: 'Desfazer',
    fn: async () => {
      try {
        await undoFn();
        toast('Restaurado.', 'success');
        if (typeof refreshData === 'function') await refreshData();
      } catch (e) {
        toast('Não foi possível desfazer: ' + (e.message || 'erro'), 'error');
      }
    }
  });
}
/* ── CONFETE ──
   Explosão com física simples: cada pedaço sai da origem num ângulo pra
   cima, perde velocidade e cai com gravidade, girando. A trajetória vira
   keyframes da Web Animations API (sem canvas, sem lib). Cores: roxo da
   marca (acento atual), verde de sucesso e três de apoio. */
function spawnConfetti(originX, originY, count = 36) {
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim() || '#7A00FF';
  const colors = [accent, accent, '#3CE3A0', '#F5A718', '#38BDF8', '#F472B6'];
  const ox = originX != null ? originX : window.innerWidth - 60;
  const oy = originY != null ? originY : window.innerHeight - 60;
  const layer = document.createElement('div');
  layer.className = 'confetti-layer';
  document.body.appendChild(layer);
  let longest = 0;
  for (let i = 0; i < count; i++) {
    const p = document.createElement('span');
    const shape = i % 3; // 0 retângulo, 1 fita, 2 bolinha
    p.className = 'confetti-piece confetti-piece--' + ['rect', 'strip', 'dot'][shape];
    p.style.background = colors[i % colors.length];
    p.style.left = ox + 'px';
    p.style.top = oy + 'px';
    layer.appendChild(p);
    // Leque de ~110° apontado pra cima (levemente pra esquerda: a origem
    // costuma estar no canto direito da tela).
    const ang = (-90 - 12 + (Math.random() - 0.5) * 110) * Math.PI / 180;
    const speed = 520 + Math.random() * 480;          // px/s
    const vx = Math.cos(ang) * speed, vy = Math.sin(ang) * speed;
    const g = 1100, drag = 0.9;                        // px/s², atrito do ar
    const dur = 1300 + Math.random() * 700;
    const spin = (Math.random() - 0.5) * 1440;
    const tilt = Math.random() * 360;
    const frames = [];
    const N = 14;
    for (let k = 0; k <= N; k++) {
      const t = (k / N) * dur / 1000;
      const damp = (1 - Math.pow(drag, t * 10)) / (1 - drag) / 10; // integra velocidade com atrito
      const x = vx * damp;
      const y = vy * damp + 0.5 * g * t * t;
      frames.push({
        transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) rotate(${(tilt + spin * k / N).toFixed(0)}deg) rotateX(${(spin * 1.5 * k / N).toFixed(0)}deg)`,
        opacity: k < N * 0.7 ? 1 : 1 - (k - N * 0.7) / (N * 0.3),
      });
    }
    const delay = Math.random() * 60;
    p.animate(frames, { duration: dur, delay, easing: 'linear', fill: 'forwards' });
    longest = Math.max(longest, dur + delay);
  }
  setTimeout(() => layer.remove(), longest + 100);
}
/* Conclusão de demanda: toast próprio (título + nome da demanda) e confete
   saindo do ícone do toast. Usado por todos os caminhos que concluem:
   seletor de etapa, botão Avançar, arrastar no kanban e ação em lote. */
function celebrateCompletion(title, sub, action = null) {
  const t = toast({ title, sub }, 'celebrate', action);
  requestAnimationFrame(() => {
    const ic = t?.querySelector('.toast-check');
    const r = (ic || t)?.getBoundingClientRect();
    if (r) spawnConfetti(r.left + r.width / 2, r.top + r.height / 2);
  });
}
const TOAST_ICONS = {
  error: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M15 9l-6 6M9 9l6 6"/></svg>',
  warn:  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><path d="M12 9v4M12 17h.01"/></svg>',
  info:  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 16v-4M12 8h.01"/></svg>',
};
function toast(msg, type = 'success', action = null) {
  const t = document.createElement('div');
  t.className = 'toast toast-' + type;
  // Success ganha o disco com checkmark que se desenha (SVG path com dasharray).
  // Os demais tipos ganham um ícone estático colorido conforme a severidade.
  if (type === 'success' || type === 'celebrate') {
    const check = document.createElement('span');
    check.className = 'toast-check';
    check.innerHTML = '<svg viewBox="0 0 24 24"><path d="M5 12 L10 17 L19 7"/></svg>';
    t.appendChild(check);
  } else if (TOAST_ICONS[type]) {
    const ic = document.createElement('span');
    ic.className = 'toast-icon toast-icon-badge toast-icon-' + type;
    ic.innerHTML = TOAST_ICONS[type];
    t.appendChild(ic);
  }
  const msgEl = document.createElement('span');
  msgEl.className = 'toast-msg';
  if (msg && typeof msg === 'object') {
    // { title, sub }: título forte + linha de apoio (ex.: nome da demanda).
    const ti = document.createElement('b'); ti.className = 'toast-title'; ti.textContent = msg.title || '';
    msgEl.appendChild(ti);
    if (msg.sub) { const su = document.createElement('span'); su.className = 'toast-sub'; su.textContent = msg.sub; msgEl.appendChild(su); }
  } else {
    msgEl.textContent = msg;
  }
  t.appendChild(msgEl);
  let hasAction = false;
  if (action && action.label && typeof action.fn === 'function') {
    hasAction = true;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'toast-action';
    btn.textContent = action.label;
    btn.addEventListener('click', e => {
      e.stopPropagation();
      try { action.fn(); } catch (err) { console.error(err); }
      dismissToast(t);
    });
    t.appendChild(btn);
  }
  // Sincroniza a barra de progresso da base do toast com o timeout real.
  const durationMs = hasAction ? 6000 : type === 'celebrate' ? 5000 : 3500;
  t.style.setProperty('--toast-duration', durationMs + 'ms');
  $('toast-container').appendChild(t);
  // Mouse em cima pausa o tempo (a barra pausa via CSS :hover).
  let remaining = durationMs, startedAt = Date.now();
  let timer = setTimeout(() => dismissToast(t), remaining);
  t.addEventListener('mouseenter', () => { clearTimeout(timer); remaining -= Date.now() - startedAt; });
  t.addEventListener('mouseleave', () => {
    startedAt = Date.now();
    timer = setTimeout(() => dismissToast(t), Math.max(remaining, 800));
  });
  return t;
}
/* Saída do toast: fixa a altura atual e deixa o CSS (.is-leaving) recolher,
   pra os toasts de cima descerem suavemente em vez de pularem. */
function dismissToast(t) {
  if (!t || t._leaving || !t.isConnected) return;
  t._leaving = true;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { t.remove(); return; }
  t.style.height = t.offsetHeight + 'px';
  void t.offsetHeight;
  t.classList.add('is-leaving');
  t.style.height = '0px';
  setTimeout(() => t.remove(), 320);
}
/* ─── ATALHOS DE TECLADO ─── */
const KB_SHORTCUTS = [
  { keys: ['⌘/Ctrl', 'K'], label: 'Paleta de comandos (busca + ações)' },
  { keys: ['?'],       label: 'Mostrar atalhos' },
  { keys: ['/'],       label: 'Focar na busca' },
  { keys: ['n'],       label: 'Nova demanda' },
  { keys: ['g', 'd'],  label: 'Ir para Início' },
  { keys: ['g', 'l'],  label: 'Ir para Demandas' },
  { keys: ['g', 'm'],  label: 'Ir para Minhas Demandas' },
  { keys: ['g', 'c'],  label: 'Ir para Capacidade' },
  { keys: ['g', 'p'],  label: 'Ir para Projetos' },
  { keys: ['Esc'],     label: 'Fechar modal/painel' },
];
let _gPressed = false;
/* Detecta se o foco está num campo de texto (input, textarea, select,
   contenteditable ou elemento com role="textbox"/"combobox"). Usado pra
   bloquear TODOS os atalhos rápidos — incluindo Ctrl/Cmd+K — enquanto
   o usuário digita, evitando roubar teclas dele. */
function isEditableTarget(t) {
  if (!t || !t.tagName) return false;
  const tag = t.tagName;
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag === 'INPUT') {
    // Checkbox/radio/button/hidden não são "de texto" — atalhos podem passar.
    const type = (t.type || 'text').toLowerCase();
    return !['checkbox','radio','button','submit','reset','file','hidden','image','color','range'].includes(type);
  }
  if (t.isContentEditable) return true;
  const role = t.getAttribute && t.getAttribute('role');
  if (role === 'textbox' || role === 'combobox' || role === 'searchbox') return true;
  return false;
}
function initKeyboardShortcuts() {
  document.addEventListener('keydown', e => {
    const t = e.target;
    const inEditable = isEditableTarget(t);
    // Esc sempre — fecha popovers/cheatsheet mesmo digitando (é UX esperada).
    if (e.key === 'Escape') {
      if (cmdkOpen) { e.preventDefault(); closeCommandPalette(); return; }
      if (hideShortcutsHelp()) { e.preventDefault(); return; }
      return;
    }
    // Se está num campo de texto, bloqueia TODOS os atalhos (inclusive Ctrl+K).
    // Exceção: se o cmdk está aberto, Ctrl+K fecha ele mesmo com foco no input.
    if (inEditable) {
      if (cmdkOpen && (e.ctrlKey || e.metaKey) && !e.altKey && (e.key === 'k' || e.key === 'K')) {
        e.preventDefault();
        closeCommandPalette();
      }
      return;
    }
    // Ctrl/Cmd+K abre paleta de comandos (fora de campos de texto).
    if ((e.ctrlKey || e.metaKey) && !e.altKey && (e.key === 'k' || e.key === 'K')) {
      e.preventDefault();
      if (cmdkOpen) closeCommandPalette();
      else openCommandPalette();
      return;
    }
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const k = e.key;
    _godmodeCheckKey(k);
    if (k === '?') { e.preventDefault(); showShortcutsHelp(); }
    else if (k === '/') { e.preventDefault(); const s = $('search-input'); if (s) s.focus(); }
    else if (k === 'n') { e.preventDefault(); if (typeof openNewDemand === 'function') openNewDemand(); }
    else if (k === 'g') { _gPressed = true; setTimeout(() => { _gPressed = false; }, 800); }
    else if (_gPressed) {
      const go = { d: 'dashboard', l: 'list', m: 'mine', c: 'analytics', p: 'projects' }[k];
      if (go) { e.preventDefault(); _gPressed = false; goPage(go); }
    }
  });
}

const GODMODE_SEQ = ['1', '9', '8', '4'];
let _godmodeSeqIdx = 0;
let _godmodeSeqTimer = null;
function _godmodeCheckKey(k) {
  if (k === GODMODE_SEQ[_godmodeSeqIdx]) {
    _godmodeSeqIdx++;
    clearTimeout(_godmodeSeqTimer);
    _godmodeSeqTimer = setTimeout(() => { _godmodeSeqIdx = 0; }, 2000);
    if (_godmodeSeqIdx >= GODMODE_SEQ.length) {
      _godmodeSeqIdx = 0;
      clearTimeout(_godmodeSeqTimer);
      // Silencioso pra não-admin — sem toast, sem log, sem nada.
      if (typeof me !== 'undefined' && me && me.isAdmin) openGodmode();
    }
  } else {
    _godmodeSeqIdx = 0;
    clearTimeout(_godmodeSeqTimer);
  }
}

let _godmodeOpen = false;
let _godmodeRefreshTimer = null;
let _godmodeSelectedId = null;
let _godmodeOverview = null;
let _godmodeSearch = '';

async function openGodmode() {
  if (_godmodeOpen) return;
  const overlay = document.getElementById('godmode-overlay');
  if (!overlay) return;
  _godmodeOpen = true;
  overlay.hidden = false;
  overlay.setAttribute('aria-hidden', 'false');
  overlay.classList.add('is-open');
  document.body.classList.add('gm-locked');
  // Handler global de Esc + click no backdrop.
  overlay.addEventListener('click', _godmodeBackdropClick);
  document.addEventListener('keydown', _godmodeOnKey, true);
  const searchEl = document.getElementById('gm-search');
  if (searchEl) {
    searchEl.value = _godmodeSearch = '';
    searchEl.oninput = () => { _godmodeSearch = (searchEl.value || '').toLowerCase().trim(); _godmodeRenderList(); };
  }
  await godmodeRefresh();
  // Auto-refresh de overview a cada 10s enquanto aberto.
  _godmodeRefreshTimer = setInterval(godmodeRefresh, 10000);
}

function closeGodmode() {
  if (!_godmodeOpen) return;
  _godmodeOpen = false;
  const overlay = document.getElementById('godmode-overlay');
  if (overlay) {
    overlay.classList.remove('is-open');
    overlay.hidden = true;
    overlay.setAttribute('aria-hidden', 'true');
    overlay.removeEventListener('click', _godmodeBackdropClick);
  }
  document.body.classList.remove('gm-locked');
  document.removeEventListener('keydown', _godmodeOnKey, true);
  if (_godmodeRefreshTimer) { clearInterval(_godmodeRefreshTimer); _godmodeRefreshTimer = null; }
  _godmodeSelectedId = null;
}

function _godmodeBackdropClick(ev) {
  if (ev.target && ev.target.id === 'godmode-overlay') closeGodmode();
}
function _godmodeOnKey(ev) {
  if (ev.key === 'Escape') { ev.preventDefault(); ev.stopPropagation(); closeGodmode(); }
}

async function godmodeRefresh() {
  try {
    const r = await api('/admin/godmode/overview');
    _godmodeOverview = r;
    _godmodeRenderHeader();
    _godmodeRenderList();
    // Se um user está selecionado, refetch detail também (silencioso).
    if (_godmodeSelectedId) godmodeSelectUser(_godmodeSelectedId, true);
  } catch (e) {
    // Fail silencioso — 403 pra não-admin, network drop, etc. Fecha painel.
    if (e && e._apiKind === 'server' && String(e.message || '').match(/administra/i)) closeGodmode();
  }
}

function _godmodeRenderHeader() {
  const el = document.getElementById('gm-header-meta');
  if (!el || !_godmodeOverview) return;
  const t = _godmodeOverview.totals;
  el.innerHTML = `<span>${t.online} online</span><span class="gm-header-dot">·</span><span>${t.inDemand} em demanda</span><span class="gm-header-dot">·</span><span>${t.users} total</span>`;
}

function _godmodeRenderList() {
  const el = document.getElementById('gm-userlist');
  if (!el || !_godmodeOverview) return;
  const q = _godmodeSearch;
  const filtered = _godmodeOverview.users.filter(u => {
    if (!q) return true;
    return (u.name || '').toLowerCase().includes(q)
        || (u.username || '').toLowerCase().includes(q)
        || (u.email || '').toLowerCase().includes(q)
        || (u.role || '').toLowerCase().includes(q);
  });
  el.innerHTML = filtered.map(u => {
    const activeCls = u.id === _godmodeSelectedId ? ' is-active' : '';
    const dotCls = u.online ? 'gm-dot gm-dot--online' : 'gm-dot gm-dot--offline';
    const rolePart = u.isAdmin ? 'Admin' : (u.isModerator ? 'Moderador' : (u.isFreelancer ? 'Freelancer' : (u.role || 'Membro')));
    const viewing = u.viewing
      ? `<div class="gm-user-view">olhando <strong>${esc(u.viewing.demandName)}</strong></div>`
      : (u.online ? '<div class="gm-user-view gm-user-view--muted">online, sem demanda aberta</div>' : `<div class="gm-user-view gm-user-view--muted">visto ${u.lastSeen ? _gmTimeAgo(u.lastSeen) : 'nunca'}</div>`);
    return `<button type="button" class="gm-user${activeCls}" onclick="godmodeSelectUser('${esc(u.id)}')">
      <span class="${dotCls}"></span>
      <span class="gm-user-avatar">${avatarHTML(u, 'avatar avatar-sm').replace(/data-user-id="[^"]+"/, '')}</span>
      <span class="gm-user-body">
        <span class="gm-user-name">${esc(u.name)}${u.tabCount > 1 ? ` <span class="gm-user-tabs" title="${u.tabCount} abas">·${u.tabCount}</span>` : ''}</span>
        <span class="gm-user-role">${esc(rolePart)}${u.active === false ? ' · <span class="gm-user-inactive">inativo</span>' : ''}</span>
        ${viewing}
      </span>
    </button>`;
  }).join('') || '<div class="gm-empty">Ninguém bate esse filtro.</div>';
  paintIcons();
}

function _gmTimeAgo(iso) {
  if (!iso) return '—';
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return '—';
  const s = Math.max(0, Math.floor((Date.now() - t) / 1000));
  if (s < 60) return `há ${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `há ${m}min`;
  const h = Math.floor(m / 60);
  if (h < 24) return `há ${h}h`;
  const d = Math.floor(h / 24);
  if (d < 30) return `há ${d}d`;
  return fmtDateTime(iso);
}
function _gmFmtCycle(ms) {
  if (ms == null || !Number.isFinite(ms) || ms < 0) return '—';
  const hours = ms / (1000 * 60 * 60);
  if (hours < 48) return (Math.round(hours * 10) / 10) + 'h';
  const days = hours / 24;
  return (Math.round(days * 10) / 10) + 'd';
}

async function godmodeSelectUser(userId, silent) {
  _godmodeSelectedId = userId;
  if (!silent) _godmodeRenderList(); // repinta active
  try {
    const d = await api('/admin/godmode/user/' + userId);
    _godmodeRenderDetail(d);
  } catch (e) {
    if (!silent) toast(e.message || 'Falha ao carregar detalhes', 'error');
  }
}

function _godmodeRenderDetail(d) {
  const el = document.getElementById('gm-main');
  if (!el || !d) return;
  const u = d.user;
  const p = d.presence;
  const s = d.stats;
  const rolePart = u.isAdmin ? 'Admin' : (u.isModerator ? 'Moderador' : (u.isFreelancer ? 'Freelancer' : (u.role || 'Membro')));
  const contactRow = (label, value, href) => value
    ? `<div class="gm-contact-row"><span class="gm-contact-label">${esc(label)}</span>${href ? `<a class="gm-contact-value" href="${esc(href)}">${esc(value)}</a>` : `<span class="gm-contact-value">${esc(value)}</span>`}</div>`
    : '';
  const wsNames = (u.workspaces || []).map(id => {
    const w = (typeof workspaces !== 'undefined' && Array.isArray(workspaces)) ? workspaces.find(x => x.id === id) : null;
    return w ? w.name : id;
  });
  const activityHtml = (d.recentActivity || []).map(ev => {
    const time = _gmTimeAgo(ev.at);
    let label = '';
    if (ev.kind === 'comment') label = `comentou em <strong>${esc(ev.demandName)}</strong>${ev.preview ? `<span class="gm-act-preview">"${esc(ev.preview)}"</span>` : ''}`;
    else if (ev.kind === 'time') label = `apontou <strong>${Number(ev.hours) || 0}h</strong> em <strong>${esc(ev.demandName)}</strong>${ev.note ? `<span class="gm-act-preview">"${esc(ev.note)}"</span>` : ''}`;
    else label = `${esc(ev.action || 'ação')} em <strong>${esc(ev.demandName)}</strong>`;
    return `<div class="gm-act-item">
      <span class="gm-act-time">${esc(time)}</span>
      <span class="gm-act-body">${label}</span>
    </div>`;
  }).join('') || '<div class="gm-empty">Sem atividade registrada.</div>';
  const assignedHtml = (d.assignedDemands || []).length
    ? `<ul class="gm-list">${d.assignedDemands.map(x => `<li class="gm-list-item"><button class="gm-jump" onclick="closeGodmode(); showDetail('${esc(x.id)}')">${esc(x.name)}</button>${x.deadline ? `<span class="gm-list-meta">prazo ${esc(fmtDate(x.deadline))}</span>` : ''}</li>`).join('')}</ul>`
    : '<div class="gm-empty">Nenhuma demanda ativa atribuída.</div>';
  el.innerHTML = `
    <div class="gm-detail">
      <div class="gm-detail-head">
        ${avatarHTML(u, 'avatar avatar-lg').replace(/data-user-id="[^"]+"/, '')}
        <div class="gm-detail-heading">
          <div class="gm-detail-name">${esc(u.name)} <span class="gm-detail-user">@${esc(u.username)}</span></div>
          <div class="gm-detail-sub">${esc(rolePart)} · ${wsNames.length ? esc(wsNames.join(', ')) : 'sem equipe'}${u.active === false ? ' · <span class="gm-user-inactive">inativo</span>' : ''}</div>
          <div class="gm-detail-state">
            <span class="gm-dot ${p.online ? 'gm-dot--online' : 'gm-dot--offline'}"></span>
            ${p.online ? `${p.tabCount} ${p.tabCount > 1 ? 'abas abertas' : 'aba aberta'}` : `offline · visto ${_gmTimeAgo(u.lastSeen)}`}
            ${p.viewing ? ` · olhando <button class="gm-jump" onclick="closeGodmode(); showDetail('${esc(p.viewing.demandId)}')">${esc(p.viewing.demandName)}</button> desde ${_gmTimeAgo(p.viewing.since)}` : ''}
          </div>
        </div>
      </div>

      <div class="gm-stats">
        <div class="gm-stat"><span class="gm-stat-num">${s.activeDemands}</span><span class="gm-stat-lbl">Demandas ativas</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${s.hoursThisWeek}h</span><span class="gm-stat-lbl">Horas apontadas / semana</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${s.activeHoursThisWeek}h</span><span class="gm-stat-lbl">Horas ativo / semana</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${s.commentsThisMonth}</span><span class="gm-stat-lbl">Comentários / mês</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${s.activityThisWeek}</span><span class="gm-stat-lbl">Ações / semana</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${s.doneThisWeek}</span><span class="gm-stat-lbl">Concluídas / semana</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${s.createdThisMonth}</span><span class="gm-stat-lbl">Criadas / mês</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${_gmFmtCycle(s.avgCycleMs)}</span><span class="gm-stat-lbl">Tempo médio / demanda${s.cycleSampleCount ? ` (n=${s.cycleSampleCount})` : ''}</span></div>
        <div class="gm-stat"><span class="gm-stat-num">${s.latePercent == null ? '—' : s.latePercent + '%'}</span><span class="gm-stat-lbl">Atraso${s.deadlineCount ? ` (${s.lateCount}/${s.deadlineCount})` : ''}</span></div>
      </div>

      <div class="gm-cols">
        <section class="gm-col">
          <div class="gm-col-title">Contato</div>
          ${contactRow('E-mail', u.email, u.email ? 'mailto:' + u.email : null)}
          ${contactRow('Telefone', u.phone, u.phone ? 'tel:' + String(u.phone).replace(/[^\d+]/g,'') : null)}
          ${contactRow('Discord', u.discord || u.discordId, null)}
          ${contactRow('Google Calendar', u.googleConnected ? 'Conectado' : null, null)}
          ${contactRow('IPs de acesso conhecidos', u.knownIpCount ? String(u.knownIpCount) : null, null)}
          ${contactRow('Cadastrado em', u.createdAt ? fmtDateTime(u.createdAt) : null, null)}
        </section>
        <section class="gm-col">
          <div class="gm-col-title">Demandas atribuídas (${(d.assignedDemands || []).length})</div>
          ${assignedHtml}
        </section>
      </div>

      <section class="gm-activity">
        <div class="gm-col-title">Atividade recente</div>
        ${activityHtml}
      </section>
    </div>`;
  paintIcons();
}

/* ─── BUSCA (Ctrl K) ───
   Uma lista só, em seções curtas. Sem texto: 3 recentes, 3 mais usados e
   3 das minhas demandas (ações aparecem ao digitar). Com texto: um índice montado na abertura
   (acento e caixa ignorados, várias palavras = todas precisam casar), com os
   resultados agrupados por tipo. ↑ ↓ andam; Enter abre; Esc limpa e depois fecha.
   Uso por pessoa em localStorage: cada demanda/cliente/projeto/tela aberta
   (por aqui ou pelo app) conta pra Recentes e Mais usados.
   Desempenho: o índice é montado uma vez por abertura, a lista só redesenha
   o necessário, um listener só (delegação) e os ícones vêm de um cache de SVG. */
let cmdkOpen = false;
let _cmdk = { q: '', items: [], active: 0, index: null };
// Grupos dos resultados com texto (na ordem do melhor resultado de cada um).
const CMDK_GROUPS = [
  { kinds: ['page', 'action'], title: 'Telas e ações', max: 5 },
  { kinds: ['demand'], title: 'Demandas', max: 8 },
  { kinds: ['client'], title: 'Clientes', max: 5 },
  { kinds: ['project'], title: 'Projetos', max: 5 },
  { kinds: ['user'], title: 'Pessoas', max: 5 },
];
const CMDK_KIND_LABEL = { demand: 'Demanda', client: 'Cliente', project: 'Projeto', user: 'Pessoa', page: 'Tela', action: 'Ação', lista: 'Lista', recurring: 'Recorrente', flow: 'Fluxo' };

/* Uso (Recentes / Mais usados): { chave: { n, t } }, chaves 'd:id' 'c:id' 'p:id' 'u:id' 'pg:pagina' 'a:acao'. */
let _cmdkUse = null, _cmdkUseTimer = null;
const _cmdkUseKey = () => 'kastor-cmdk-use-' + (me?.id || 'anon');
function _cmdkUsage() {
  if (!_cmdkUse) { try { _cmdkUse = JSON.parse(localStorage.getItem(_cmdkUseKey()) || '{}') || {}; } catch { _cmdkUse = {}; } }
  return _cmdkUse;
}
function cmdkTrack(key) {
  if (!me || !key) return;
  const u = _cmdkUsage();
  u[key] = { n: (u[key]?.n || 0) + 1, t: Date.now() };
  clearTimeout(_cmdkUseTimer);
  _cmdkUseTimer = setTimeout(() => {
    const keys = Object.keys(u);
    if (keys.length > 250) keys.sort((a, b) => u[a].t - u[b].t).slice(0, keys.length - 250).forEach(k => delete u[k]);
    try { localStorage.setItem(_cmdkUseKey(), JSON.stringify(u)); } catch {}
  }, 400);
}

/* Ações (curtas) — telas vêm do catálogo do menu (NAV_CATALOG). */
function _cmdkActions() {
  return [
    { id: 'new-demand', icon: 'plus', label: 'Nova demanda', hint: 'N', run: () => openNewDemand() },
    { id: 'new-client', icon: 'building-2', label: 'Novo cliente', staff: true, run: () => openClientModal(null) },
    { id: 'new-lista', icon: 'list-checks', label: 'Nova lista recorrente', staff: true, run: () => openNovaListaModal() },
    { id: 'status', icon: 'headphones', label: 'Mudar meu status', run: () => toggleStatusMenu() },
    { id: 'profile', icon: 'user-cog', label: 'Configurações (meu perfil)', run: () => goPage('profile') },
    { id: 'quick', icon: 'sliders-horizontal', label: 'Editar acesso rápido', staff: true, run: () => goPage('menu') },
    { id: 'theme', icon: 'sun-moon', label: 'Alternar tema claro/escuro', run: () => toggleTheme() },
    { id: 'sidebar', icon: 'panel-left', label: 'Recolher/expandir menu lateral', run: () => toggleSidebarCollapse() },
    { id: 'shortcuts', icon: 'keyboard', label: 'Atalhos de teclado', hint: '?', run: () => showShortcutsHelp() },
  ].filter(a => !a.staff || !(me?.isFreelancer && !me.isAdmin && !me.isModerator))
   .map(a => ({ key: 'a:' + a.id, kind: 'action', icon: a.icon, label: a.label, hint: a.hint, run: a.run }));
}
function _cmdkPages() {
  const extra = [
    { page: 'profile', label: 'Meu perfil', icon: 'user-cog' },
    { page: 'help', label: 'Documentação', icon: 'circle-help', cls: 'freelancer-hide' },
    { page: 'analytics', tab: 'capacity', label: 'Análises · Capacidade', icon: 'gauge', cls: 'freelancer-hide' },
    { page: 'analytics', tab: 'rhythm', label: 'Análises · Ritmo', icon: 'activity', cls: 'freelancer-hide' },
    { page: 'analytics', tab: 'reports', label: 'Análises · Relatórios', icon: 'timer', cls: 'freelancer-hide' },
  ];
  return [...NAV_CATALOG, ...extra].filter(_navAllowed).map(p => ({
    key: 'pg:' + p.page + (p.tab ? ':' + p.tab : ''), kind: 'page', icon: p.icon, label: p.label,
    run: () => { goPage(p.page); if (p.tab) setTimeout(() => setAnalyticsTab(p.tab), 30); },
  }));
}
// Índice da busca: montado ao abrir (os dados mudam pouco enquanto a busca está aberta).
function _cmdkBuildIndex() {
  const out = [];
  const add = it => { it.hay = norm(it.label); it.haySub = norm(it.sub || ''); out.push(it); };
  const inWs = x => !activeWs || x.workspaceId === activeWs;
  (clients || []).filter(c => !c.deletedAt && inWs(c)).forEach(c => add({ key: 'c:' + c.id, kind: 'client', icon: 'building-2', label: c.name, run: () => openClient(c.id) }));
  (projects || []).filter(p => !p.deletedAt && inWs(p)).forEach(p => add({ key: 'p:' + p.id, kind: 'project', icon: 'folder', label: p.name,
    sub: clientById(p.clientId)?.name || p.client || '', run: () => openProjectDetail(p.id) }));
  (demands || []).filter(d => !d.deletedAt && inWs(d)).forEach(d => {
    const p = projectById(d.projectId);
    add({ key: 'd:' + d.id, kind: 'demand', icon: isDone(d) ? 'circle-check' : 'square', label: d.name, done: isDone(d),
      sub: [clientById(p?.clientId)?.name, p?.name].filter(Boolean).join(' · '), run: () => showDetail(d.id) });
  });
  (users || []).filter(u => u.active !== false && !u.deletedAt).forEach(u => add({ key: 'u:' + u.id, kind: 'user', icon: 'user', label: u.name,
    sub: u.role || (u.username ? '@' + u.username : ''), run: () => { if (me?.isAdmin) openUserModal(u.id); else goPage('users'); } }));
  _cmdkPages().forEach(add);
  _cmdkActions().forEach(add);
  return out;
}
// Casa todas as palavras (no nome ou no complemento). Nome vale mais; começo de palavra vale mais.
function _cmdkScore(it, tokens) {
  let s = 0;
  for (const t of tokens) {
    const i = it.hay.indexOf(t);
    if (i >= 0) { s += i === 0 ? 40 : it.hay[i - 1] === ' ' ? 26 : 12; continue; }
    const j = it.haySub.indexOf(t);
    if (j < 0) return -1;
    s += j === 0 || it.haySub[j - 1] === ' ' ? 8 : 4;
  }
  const u = _cmdkUsage()[it.key];
  if (u) s += Math.min(24, u.n * 3) + (Date.now() - u.t < 3 * 864e5 ? 8 : 0);
  if (it.done) s -= 15;
  if (it.kind === 'page' || it.kind === 'action') s += 6;
  return s;
}
function _cmdkSearch(q) {
  const tokens = norm(q).split(/\s+/).filter(Boolean);
  const scored = [];
  for (const it of _cmdk.index) { const sc = _cmdkScore(it, tokens); if (sc >= 0) scored.push([sc, it]); }
  scored.sort((a, b) => b[0] - a[0] || a[1].label.length - b[1].label.length);
  return scored.map(x => x[1]);
}
// Resolve uma chave de uso no item atual (some quem foi apagado ou saiu do squad).
function _cmdkResolve(key) { return _cmdk.byKey?.get(key) || null; }
function _cmdkTabItems(tab) {
  const u = _cmdkUsage();
  if (tab === 'actions') return _cmdk.index.filter(it => it.kind === 'action').map((it, i) => [it, u[it.key]?.n || 0, i])
    .sort((a, b) => b[1] - a[1] || a[2] - b[2]).map(x => x[0]);
  if (tab === 'mine') {
    const today = todayStr();
    return myDemands().filter(d => !isDone(d))
      .sort((a, b) => (effDue(a) || '9999').localeCompare(effDue(b) || '9999'))
      .slice(0, 30).map(d => {
        const it = _cmdkResolve('d:' + d.id); if (!it) return null;
        const due = effDue(d);
        return { ...it, meta: due ? (due < today ? 'Atrasada' : due === today ? 'Hoje' : fmtPfpShort(due)) : '', late: !!due && due < today };
      }).filter(Boolean);
  }
  const keys = Object.keys(u);
  if (tab === 'recent') keys.sort((a, b) => u[b].t - u[a].t);
  // Mais usados: contagem com peso por recência (meia-vida de 14 dias).
  else keys.sort((a, b) => u[b].n * Math.pow(0.5, (Date.now() - u[b].t) / (14 * 864e5)) - u[a].n * Math.pow(0.5, (Date.now() - u[a].t) / (14 * 864e5)));
  const out = [];
  for (const k of keys) {
    const it = _cmdkResolve(k);
    if (!it || (tab === 'recent' && it.kind === 'action')) continue;
    out.push(tab === 'recent' ? { ...it, meta: fmtRelativeTime(new Date(u[k].t).toISOString()).replace(/^há /, '') } : it);
    if (out.length >= 12) break;
  }
  return out;
}

/* Ícones: cache do SVG pronto por nome (lucide só roda pra ícone novo). */
const _cmdkSvg = {};
const _cmdkIcon = n => _cmdkSvg[n] || `<i data-lucide="${n}"></i>`;
function _cmdkHarvestIcons(root) {
  if (root.querySelector('i[data-lucide]')) paintIcons(root);
  root.querySelectorAll('svg[data-lucide]').forEach(s => { const n = s.getAttribute('data-lucide'); if (!_cmdkSvg[n]) _cmdkSvg[n] = s.outerHTML; });
}
// Destaca o trecho que casou (sem acento/caixa) no nome.
function _cmdkMark(label, tokens) {
  if (!tokens.length) return esc(label);
  const n = norm(label);
  const hit = new Array(label.length).fill(false);
  tokens.forEach(t => { let i = n.indexOf(t); while (i >= 0 && t) { for (let k = i; k < i + t.length; k++) hit[k] = true; i = n.indexOf(t, i + t.length); } });
  let html = '', on = false;
  for (let i = 0; i < label.length; i++) {
    if (hit[i] !== on) { html += hit[i] ? '<mark>' : '</mark>'; on = hit[i]; }
    html += esc(label[i]);
  }
  return html + (on ? '</mark>' : '');
}

function openCommandPalette() {
  let el = document.getElementById('cmdk');
  if (!el) {
    el = document.createElement('div');
    el.id = 'cmdk';
    el.className = 'cmdk-overlay';
    el.innerHTML = `
      <div class="cmdk-card" role="dialog" aria-modal="true" aria-label="Buscar">
        <div class="cmdk-input-wrap">
          <i data-lucide="search" class="cmdk-input-icon"></i>
          <input class="cmdk-input" id="cmdk-input" placeholder="Buscar demanda, cliente, projeto, pessoa ou tela…" autocomplete="off" spellcheck="false"
            role="combobox" aria-expanded="true" aria-controls="cmdk-results" aria-autocomplete="list">
          <kbd class="cmdk-hint-kbd">Esc</kbd>
        </div>
        <div class="cmdk-results" id="cmdk-results" role="listbox" aria-label="Resultados"></div>
      </div>`;
    document.body.appendChild(el);
    el.addEventListener('mousedown', ev => { if (ev.target === el) closeCommandPalette(); });
    const input = el.querySelector('#cmdk-input');
    input.addEventListener('input', () => { _cmdk.q = input.value; _cmdk.active = 0; _cmdkRender(); });
    input.addEventListener('keydown', cmdkOnKey);
    const res = el.querySelector('#cmdk-results');
    res.addEventListener('mousemove', ev => {
      const row = ev.target.closest('.cmdk-item');
      if (row && +row.dataset.i !== _cmdk.active) { _cmdk.active = +row.dataset.i; _cmdkPaintActive(false); }
    });
    res.addEventListener('click', ev => { const row = ev.target.closest('.cmdk-item'); if (row) cmdkRun(_cmdk.items[+row.dataset.i]); });
    paintIcons(el.querySelector('.cmdk-input-wrap'));
  }
  _cmdk.index = _cmdkBuildIndex();
  _cmdk.byKey = new Map(_cmdk.index.map(it => [it.key, it]));
  _cmdk.q = '';
  _cmdk.active = 0;
  el.querySelector('#cmdk-input').value = '';
  el.classList.add('open');
  cmdkOpen = true;
  _cmdkRender();
  requestAnimationFrame(() => document.getElementById('cmdk-input')?.focus());
}
function closeCommandPalette() {
  document.getElementById('cmdk')?.classList.remove('open');
  cmdkOpen = false;
}
function cmdkOnKey(e) {
  const n = _cmdk.items.length;
  if (e.key === 'Escape') {
    e.preventDefault(); e.stopPropagation();
    if (_cmdk.q) { e.target.value = ''; _cmdk.q = ''; _cmdk.active = 0; _cmdkRender(); } else closeCommandPalette();
  } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    if (n) { _cmdk.active = (_cmdk.active + (e.key === 'ArrowDown' ? 1 : -1) + n) % n; _cmdkPaintActive(true); }
  } else if (e.key === 'Enter') {
    e.preventDefault();
    if (_cmdk.items[_cmdk.active]) cmdkRun(_cmdk.items[_cmdk.active]);
  }
}
function _cmdkPaintActive(scroll) {
  const rows = document.querySelectorAll('#cmdk-results .cmdk-item');
  rows.forEach((r, i) => { const on = i === _cmdk.active; r.classList.toggle('active', on); r.setAttribute('aria-selected', on); });
  const act = rows[_cmdk.active];
  document.getElementById('cmdk-input')?.setAttribute('aria-activedescendant', act ? act.id : '');
  if (scroll && act) act.scrollIntoView({ block: 'nearest' });
}
function cmdkRun(it) {
  if (!it) return;
  closeCommandPalette();
  // Entidades e telas contam pelo próprio app (showDetail, goPage…); ações contam aqui.
  if (it.kind === 'action') cmdkTrack(it.key);
  setTimeout(() => { try { it.run(); } catch (err) { console.error(err); } }, 0);
}
function _cmdkRender() {
  const out = document.getElementById('cmdk-results');
  if (!out) return;
  const q = _cmdk.q.trim();
  const tokens = norm(q).split(/\s+/).filter(Boolean);
  let sections;
  if (q) {
    const all = _cmdkSearch(q);
    const firstAt = g => all.findIndex(it => g.kinds.includes(it.kind));
    sections = CMDK_GROUPS.map(g => ({ g, at: firstAt(g) })).filter(x => x.at >= 0).sort((a, b) => a.at - b.at)
      .map(({ g }) => ({ title: g.title, kind: true, items: all.filter(it => g.kinds.includes(it.kind)).slice(0, g.max) }));
  } else {
    // Sem texto: seções curtas, sem repetir item entre elas.
    const used = new Set();
    const take = (list, n) => {
      const out = [];
      for (const it of list) { if (out.length >= n) break; if (!used.has(it.key)) { used.add(it.key); out.push(it); } }
      return out;
    };
    sections = [
      { title: 'Recentes', kind: true, items: take(_cmdkTabItems('recent'), 3) },
      { title: 'Mais usados', kind: true, items: take(_cmdkTabItems('top'), 3) },
      { title: 'Minhas demandas', items: take(_cmdkTabItems('mine'), 3) },
    ].filter(sec => sec.items.length);
  }
  const items = [];
  let html = '';
  for (const sec of sections) {
    html += `<div class="cmdk-section" role="presentation">${esc(sec.title)}</div>`;
    for (const it of sec.items) {
      const i = items.push(it) - 1;
      const right = it.meta ? `<span class="cmdk-item-meta ${it.late ? 'is-late' : ''}">${esc(it.meta)}</span>`
        : it.hint ? `<kbd class="cmdk-item-kbd">${esc(it.hint)}</kbd>` : '';
      const kind = sec.kind && CMDK_KIND_LABEL[it.kind];
      html += `<div class="cmdk-item ${it.done ? 'is-done' : ''}" id="cmdk-opt-${i}" data-i="${i}" role="option" aria-selected="false">
        <span class="cmdk-item-icon">${_cmdkIcon(it.icon)}</span>
        <span class="cmdk-item-text"><span class="cmdk-item-label">${_cmdkMark(it.label, tokens)}</span>${it.sub ? `<span class="cmdk-item-sub">${esc(it.sub)}</span>` : ''}</span>
        ${right}${kind ? `<span class="cmdk-item-kind">${kind}</span>` : ''}
      </div>`;
    }
  }
  _cmdk.items = items;
  if (_cmdk.active >= items.length) _cmdk.active = Math.max(0, items.length - 1);
  out.innerHTML = items.length ? html : `<div class="cmdk-empty">${q ? `Nada encontrado para “${esc(q)}”.` : 'Nada por aqui ainda. Digite para buscar.'}</div>`;
  // Sem texto a lista não rola: em tela baixa, some o que não cabe (nada cortado pela metade).
  if (!q) {
    while (items.length > 1 && out.scrollHeight > out.clientHeight + 1) {
      const rows = out.querySelectorAll('.cmdk-item');
      rows[rows.length - 1].remove();
      items.pop();
      if (out.lastElementChild?.classList.contains('cmdk-section')) out.lastElementChild.remove();
    }
  }
  _cmdkHarvestIcons(document.getElementById('cmdk'));
  out.scrollTop = 0;
  _cmdkPaintActive(false);
}
function showShortcutsHelp() {
  let el = document.getElementById('shortcuts-help');
  if (!el) {
    el = document.createElement('div');
    el.id = 'shortcuts-help';
    el.className = 'shortcuts-overlay';
    el.innerHTML = `
      <div class="shortcuts-card">
        <div class="shortcuts-head">
          <div class="shortcuts-title">Atalhos de teclado</div>
          <button class="modal-close" onclick="hideShortcutsHelp()" data-tooltip="Fechar"><i data-lucide="x" class="ic-sm"></i></button>
        </div>
        <div class="shortcuts-list">
          ${KB_SHORTCUTS.map(s => `<div class="shortcuts-row">
            <div class="shortcuts-keys">${s.keys.map(k => `<kbd>${esc(k)}</kbd>`).join('<span class="shortcuts-plus">depois</span>')}</div>
            <div class="shortcuts-label">${esc(s.label)}</div>
          </div>`).join('')}
        </div>
        <div class="shortcuts-hint">Atalhos não funcionam enquanto você digita em um campo.</div>
      </div>`;
    document.body.appendChild(el);
    el.addEventListener('click', ev => { if (ev.target === el) hideShortcutsHelp(); });
  }
  el.classList.add('open');
  paintIcons();
}
function hideShortcutsHelp() {
  const el = document.getElementById('shortcuts-help');
  if (!el || !el.classList.contains('open')) return false;
  el.classList.remove('open');
  return true;
}

/* ─── TOOLTIPS GLOBAIS — DESATIVADAS ───
   O sistema custom tinha bugs recorrentes (travar na tela, abrir fora da
   viewport, ghost quando o alvo saía do DOM). Removido. Qualquer atributo
   `title=` continua funcionando via tooltip nativo do navegador.
   O código antigo abaixo (`_legacyTooltipInit_OFF`) é mantido só como
   histórico — nada o chama. `initTooltips()` agora só varre o DOM pra
   remover qualquer bolha ghost `.tt` que possa ter sobrado. */
let _tooltipEl = null;
