function tflStagePresetDone(i) { const r = _tflCtx && _tflCtx.stages[Number(i)]; if (r && !r.done) tflToggleDone(Number(i)); }
function wizardStagePresetDone(stageId) { wizardCustSetDone(stageId, true); }
