async function sendComment() {
  const el = $('comment-input');
  if (!el) return;
  const html = _commentInputHtml(el);
  const plain = _commentInputPlain(el);
  const hasImg = /<img\b/i.test(html);
  if (!plain.trim() && !pendingAttachments.length && !hasImg) return;
  try {
    const upd = await api('/demands/' + detailId + '/comment', 'POST', {
      text: html,
      format: 'html',
      attachments: pendingAttachments
    });
    pendingAttachments = [];
    hideCommentGhost();
    ensureCommentPhrases(true);
    _clearNewSince();
    draftClearComment(detailId); // rascunho salvou seu papel — pode sair
    // Limpa o compose ANTES de renderDetail — sem isso, o snapshot que roda no topo
    // do renderDetail captura o texto já enviado e o draftRestoreComment repõe.
    el.innerHTML = '';
    syncCommentEmptyState(el);
    patchDemand(upd);
    renderDetail();
    _pendingMentionsCache = null;
    // Mencionou alguém que está fora: avisa (ela só vê quando voltar).
    const sentC = (upd.comments || [])[upd.comments.length - 1];
    const awayMentioned = (sentC?.mentions || []).map(userById).filter(u => u && u.id !== me.id && awayState(u)?.active);
    if (awayMentioned.length) {
      const u0 = awayMentioned[0], st0 = awayState(u0);
      const msg = awayMentioned.length === 1
        ? `${u0.name.split(' ')[0]} está fora até ${fmtDateShort(st0.to)}${st0.sub ? ` — quem cobre é ${st0.sub.name.split(' ')[0]}` : ''}.`
        : `${awayMentioned.map(u => u.name.split(' ')[0]).join(', ')} estão fora. Vão ver quando voltarem.`;
      setTimeout(() => toast(msg, 'warn'), 400);
    }
    // Link no comentário (entrega por Dropbox/Drive etc.) que ainda não está
    // nos anexos: oferece anexar com um clique.
    const demandId = detailId;
    const newLinks = _linksNotAttached(demandById(demandId), _extractCommentLinks(html, plain));
    if (newLinks.length) {
      toast(newLinks.length === 1 ? 'Comentário enviado. Anexar o link à demanda?' : `Comentário enviado. Anexar os ${newLinks.length} links à demanda?`,
        'success', { label: 'Anexar', fn: () => attachCommentLinks(demandId, newLinks) });
    } else {
      toast('Comentário enviado!');
    }
  } catch (e) { toast(e.message, 'error'); }
}
// URLs do comentário: texto digitado + href de links clicáveis. Tira
// pontuação grudada no fim ("veja https://x.com/a." → sem o ponto).
function _extractCommentLinks(html, plain) {
  const found = [];
  const push = u => {
    const clean = String(u || '').replace(/&amp;/g, '&').replace(/[.,;:!?)\]}>'"]+$/, '');
    if (/^https?:\/\/[^\s]+\.[^\s]+/i.test(clean)) found.push(clean);
  };
  (String(plain || '').match(/\bhttps?:\/\/[^\s<>"]+/gi) || []).forEach(push);
  (String(html || '').match(/href="(https?:\/\/[^"]+)"/gi) || []).forEach(m => push(m.slice(6, -1)));
  return [...new Set(found)];
}
