const _DRAFT_KEY = id => 'kastor-draft-comment-' + id;
let _draftSaveTimer = null;
/* ── RESPOSTAS PRONTAS ──
   Textos curtos por usuário (salvos em me.quickReplies no server; null = usa
   as sugestões padrão). Abre pelo botão do compositor ou digitando "/" no
   começo do comentário — aí filtra pelo que vem depois da barra e Enter usa
   a primeira. */
const QUICK_REPLY_DEFAULTS = [
  'Enviado para aprovação do cliente.',
  'Ajustes aplicados, pode conferir.',
  'Aguardando material do cliente para seguir.',
  'Arquivos finais anexados.',
];
let _qrFilter = null; // string quando aberto via "/", null quando pelo botão
function quickRepliesOf() { return Array.isArray(me?.quickReplies) ? me.quickReplies : QUICK_REPLY_DEFAULTS; }
function _qrVisible() {
  const list = quickRepliesOf();
  const f = _qrFilter ? norm(_qrFilter) : '';
  return list.map((text, i) => ({ text, i })).filter(x => !f || norm(x.text).includes(f));
}
// Frases aprendidas que ainda não estão nas respostas salvas (mesmo filtro).
function _qrLearnedVisible() {
  const saved = new Set(quickRepliesOf().map(t => norm(t).replace(/[\s.!?]+$/, '')));
  const f = _qrFilter ? norm(_qrFilter) : '';
  return (_commentPhrases || [])
    .map((p, i) => ({ ...p, i, label: p.text.replace(/\{link\}/g, '[link]') }))
    .filter(p => !saved.has(norm(_phraseCompletion(p.text)).replace(/[\s.!?]+$/, '')))
    .filter(p => !f || norm(p.label).includes(f));
}
function renderQuickReplies() {
  const pop = $('qr-pop'); if (!pop) return;
  const items = _qrVisible();
  const learned = _qrLearnedVisible();
  const el = $('comment-input');
  const canSave = _qrFilter === null && el && el.innerText.trim();
  pop.innerHTML = `
    <div class="qr-head">Respostas prontas</div>
    <div class="qr-list">
      ${items.length ? items.map((x, n) => `
        <div class="qr-row${_qrFilter !== null && n === 0 ? ' is-first' : ''}">
          <button type="button" class="qr-item" onmousedown="event.preventDefault()" onclick="insertQuickReply(${x.i})">${esc(x.text)}</button>
          <button type="button" class="qr-del" title="Remover" onmousedown="event.preventDefault()" onclick="removeQuickReply(${x.i})"><i data-lucide="x" class="ic-xs"></i></button>
        </div>`).join('')
      : (learned.length ? '' : `<div class="qr-empty">${_qrFilter ? 'Nenhuma resposta com “' + esc(_qrFilter) + '”.' : 'Nenhuma resposta salva.'}</div>`)}
      ${learned.length ? `<div class="qr-head qr-head-sub">Do seu histórico</div>` + learned.map((p, n) => `
        <div class="qr-row${_qrFilter !== null && !items.length && n === 0 ? ' is-first' : ''}">
          <button type="button" class="qr-item" title="Você usou ${p.count} vezes" onmousedown="event.preventDefault()" onclick="insertLearnedPhrase(${p.i})">${esc(p.label)}</button>
          <button type="button" class="qr-del qr-pin" title="Salvar nas respostas prontas" onmousedown="event.preventDefault()" onclick="pinLearnedPhrase(${p.i})"><i data-lucide="bookmark-plus" class="ic-xs"></i></button>
        </div>`).join('') : ''}
    </div>
    <button type="button" class="qr-save" onmousedown="event.preventDefault()" onclick="saveQuickReplyFromInput()" ${canSave ? '' : 'disabled'}>
      <i data-lucide="bookmark-plus" class="ic-xs"></i> Salvar texto atual como resposta
    </button>`;
  pop.hidden = false;
  // Fixed (o compositor tem overflow:hidden): logo acima do campo de texto.
  const r = (el || pop.parentElement).getBoundingClientRect();
  pop.style.left = Math.max(8, r.left) + 'px';
  pop.style.bottom = Math.max(8, window.innerHeight - r.top + 6) + 'px';
  pop.style.width = Math.min(360, Math.max(260, r.width)) + 'px';
  paintIcons();
}
function closeQuickReplies() {
  const pop = $('qr-pop'); if (pop) pop.hidden = true;
  _qrFilter = null;
}
function toggleQuickReplies(ev) {
  ev?.stopPropagation();
  const pop = $('qr-pop'); if (!pop) return;
  if (!pop.hidden && _qrFilter === null) return closeQuickReplies();
  _qrFilter = null;
  renderQuickReplies();
}
function quickReplyWatch(el) {
  const txt = (el.innerText || '').replace(/\u00a0/g, ' ').trim();
  const m = txt.match(/^\/([^\s/]*)$/);
  if (m) { _qrFilter = m[1]; renderQuickReplies(); }
  else if (_qrFilter !== null) closeQuickReplies();
}
// true = tecla consumida (não repassa pro handler de menções).
function quickReplyKeys(e) {
  const pop = $('qr-pop');
  if (!pop || pop.hidden) return false;
  if (e.key === 'Escape') { e.preventDefault(); closeQuickReplies(); return true; }
  if (e.key === 'Enter' && _qrFilter !== null) {
    const first = _qrVisible()[0];
    const learned = first ? null : _qrLearnedVisible()[0];
    if (!first && !learned) return false;
    e.preventDefault();
    if (first) insertQuickReply(first.i); else insertLearnedPhrase(learned.i);
    return true;
  }
  return false;
}
function insertQuickReply(i) { _insertCommentText(quickRepliesOf()[i]); }
function insertLearnedPhrase(i) {
  const p = (_commentPhrases || [])[i];
  if (p) _insertCommentText(_phraseCompletion(p.text));
}
async function pinLearnedPhrase(i) {
  const p = (_commentPhrases || [])[i];
  if (!p) return;
  const text = _phraseCompletion(p.text).trim();
  const list = quickRepliesOf();
  if (list.includes(text)) return;
  if (await _saveQuickReplies(list.concat(text))) { toast('Resposta salva.'); renderQuickReplies(); }
}
function _insertCommentText(text) {
  const el = $('comment-input');
  if (!text || !el) return;
  el.focus();
  if (_qrFilter !== null) el.innerHTML = ''; // troca o "/filtro" pela resposta
  // Caret fora do editor (abriu pelo botão sem clicar no texto): vai pro fim.
  const sel = window.getSelection();
  if (!sel.rangeCount || !el.contains(sel.anchorNode)) {
    const r = document.createRange();
    r.selectNodeContents(el); r.collapse(false);
    sel.removeAllRanges(); sel.addRange(r);
  }
  document.execCommand('insertText', false, text);
  closeQuickReplies();
  document.getElementById('chat-compose')?.classList.add('is-active');
  draftSaveCommentCE(el);
  syncCommentEmptyState(el);
}
async function _saveQuickReplies(list) {
  try {
    me = await api('/me', 'PUT', { quickReplies: list });
    return true;
  } catch (e) { toast(e.message, 'error'); return false; }
}
async function saveQuickReplyFromInput() {
  const el = $('comment-input');
  const text = (el?.innerText || '').replace(/\u00a0/g, ' ').trim();
  if (!text) return;
  const list = quickRepliesOf();
  if (list.includes(text)) { toast('Essa resposta já está salva.', 'info'); return; }
  if (await _saveQuickReplies(list.concat(text))) { toast('Resposta salva.'); renderQuickReplies(); }
}
async function removeQuickReply(i) {
  const list = quickRepliesOf().slice();
  list.splice(i, 1);
  if (await _saveQuickReplies(list)) renderQuickReplies();
}
document.addEventListener('click', e => {
  const pop = document.getElementById('qr-pop');
  if (!pop || pop.hidden || e.target.closest?.('#qr-pop')) return;
  closeQuickReplies();
});

/* ── AUTOCOMPLETAR (texto-fantasma + Tab) ──
   Enquanto a pessoa digita o COMEÇO de uma linha do comentário, sugere o resto
   de uma sequência que ela costuma usar (aprendida no server a partir de 5
   usos nos últimos 30 dias — ver learnCommentPhrases) ou de uma resposta
   pronta salva. O resto aparece em
   cinza depois do cursor; Tab aceita, Esc dispensa. Frase com link ("Segue:
   {link}") completa só até o link. */
let _commentPhrases = null;   // [{ text, count }] do server; null = não carregou
let _phrasesLoading = null;
let _ghostText = '';
let _ghostDismissed = false;
function ensureCommentPhrases(force) {
  if (!force && (_commentPhrases || _phrasesLoading)) return _phrasesLoading;
  _phrasesLoading = api('/me/comment-phrases')
    .then(list => { _commentPhrases = Array.isArray(list) ? list : []; })
    .catch(() => { _commentPhrases = _commentPhrases || []; })
    .finally(() => { _phrasesLoading = null; });
  return _phrasesLoading;
}
function _phraseCompletion(tpl) { return String(tpl || '').split('{link}')[0]; }
function _ghostCandidates() {
  const learned = (_commentPhrases || []).map(p => _phraseCompletion(p.text));
  const saved = Array.isArray(me?.quickReplies) ? me.quickReplies : [];
  return learned.concat(saved); // aprendidas já vêm da mais usada pra menos
}
function hideCommentGhost() {
  _ghostText = '';
  document.getElementById('comment-ghost')?.remove();
}
// Retângulo do cursor (range colapsado às vezes não tem rect — ex.: logo após
// um <br>; aí mede com um marcador temporário).
function _caretRect(range) {
  const r = range.getClientRects()[0];
  if (r && (r.width || r.height)) return r;
  const mark = document.createElement('span');
  mark.textContent = '\u200b';
  range.insertNode(mark);
  const rect = mark.getBoundingClientRect();
  const parent = mark.parentNode;
  mark.remove();
  parent?.normalize();
  return rect;
}
function updateCommentGhost(el) {
  hideCommentGhost();
  if (!el || _ghostDismissed || document.activeElement !== el) return;
  if ($('mention-pop')?.classList.contains('open') || $('qr-pop')?.hidden === false) return;
  // Completa a LINHA atual (as frases s\u00e3o aprendidas por come\u00e7o de linha).
  const typed = (el.innerText || '').replace(/\u00a0/g, ' ').replace(/\n+$/, '').split('\n').pop();
  if (typed.trim().length < 2) return;
  const sel = window.getSelection();
  if (!sel.rangeCount || !sel.isCollapsed || !el.contains(sel.anchorNode)) return;
  const range = sel.getRangeAt(0);
  // Só com o cursor no fim do texto (completar no meio confunde).
  const after = document.createRange();
  after.selectNodeContents(el);
  after.setStart(range.endContainer, range.endOffset);
  if (after.toString().replace(/\u200b/g, '').trim()) return;
  const nt = norm(typed);
  const hit = _ghostCandidates().find(c => c.length > typed.length && norm(c).startsWith(nt));
  if (!hit) return;
  _ghostText = hit.slice(typed.length);
  const ghost = document.createElement('div');
  ghost.id = 'comment-ghost';
  ghost.className = 'comment-ghost';
  ghost.style.font = getComputedStyle(el).font;
  ghost.innerHTML = `<span class="comment-ghost-text"></span><kbd class="comment-ghost-kbd">Tab</kbd>`;
  ghost.firstChild.textContent = _ghostText;
  document.body.appendChild(ghost);
  _placeCommentGhost(el);
  requestAnimationFrame(() => _placeCommentGhost(el));
  setTimeout(() => _placeCommentGhost(el), 250);
}
function _placeCommentGhost(el) {
  const ghost = document.getElementById('comment-ghost');
  const sel = window.getSelection();
  if (!ghost || !sel.rangeCount || !el.contains(sel.anchorNode)) return;
  const rect = _caretRect(sel.getRangeAt(0).cloneRange());
  const box = el.getBoundingClientRect();
  ghost.style.left = rect.right + 'px';
  ghost.style.top = rect.top + 'px';
  ghost.style.height = rect.height + 'px';
  ghost.style.lineHeight = rect.height + 'px';
  ghost.style.maxWidth = Math.max(0, box.right - rect.right - parseFloat(getComputedStyle(el).paddingRight || 0)) + 'px';
}
// true = tecla consumida. Tab (e Shift+Tab) nunca tira o foco do editor:
// aceita a sugestão se houver; com o popup de menções aberto, segue pra ele.
function commentGhostKeys(e) {
  if (e.key === 'Tab') {
    if ($('mention-pop')?.classList.contains('open')) return false;
    e.preventDefault();
    if (!_ghostText || e.shiftKey) return true;
    const text = _ghostText;
    hideCommentGhost();
    document.execCommand('insertText', false, text); // dispara o input (rascunho etc.)
    return true;
  }
  if (!_ghostText) return false;
  if (e.key === 'Escape') {
    e.preventDefault();
    _ghostDismissed = true;
    hideCommentGhost();
    return true;
  }
  return false;
}
// Fantasma é position:fixed — some se algo rolar embaixo dele.
document.addEventListener('scroll', () => { if (_ghostText) hideCommentGhost(); }, true);
function draftSaveCommentCE(el) {
  if (!detailId) return;
  clearTimeout(_draftSaveTimer);
  _draftSaveTimer = setTimeout(() => {
    try {
      const html = _commentInputHtml(el);
      if (html) localStorage.setItem(_DRAFT_KEY(detailId), html);
      else localStorage.removeItem(_DRAFT_KEY(detailId));
    } catch {}
  }, 300);
}
// Alias legacy — algum caller antigo pode ainda usar. Aponta pra CE.
function draftSaveComment(el) { return draftSaveCommentCE(el); }
function draftClearComment(id) {
  try { localStorage.removeItem(_DRAFT_KEY(id)); } catch {}
}
function draftRestoreComment() {
  if (!detailId) return;
  const el = document.getElementById('comment-input');
  if (!el) return;
  let saved = '';
  try { saved = localStorage.getItem(_DRAFT_KEY(detailId)) || ''; } catch {}
  if (!saved) { syncCommentEmptyState(el); return; }
  // Se ainda estiver vazio (usuário não começou a digitar entre render e restore).
  const currentHtml = (el.innerHTML || '').trim();
  const isEmpty = !currentHtml || /^<br\s*\/?>$/i.test(currentHtml);
  if (isEmpty) {
    el.innerHTML = saved;
    // Se o compose estava focado antes do render (SSE mid-typing), re-foca e joga
    // o caret no fim — assim o usuário volta exatamente onde parou de digitar.
    if (_composeWasFocused) {
      try {
        el.focus();
        const range = document.createRange();
        range.selectNodeContents(el); range.collapse(false);
        const sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(range);
      } catch {}
    }
  }
  _composeWasFocused = false;
  syncCommentEmptyState(el);
}
let _composeWasFocused = false;
async function deleteComment(cid) {
  try {
    const upd = await api('/demands/' + detailId + '/comment/' + cid, 'DELETE');
    patchDemand(upd);
    renderDetail();
  } catch (e) { toast(e.message, 'error'); }
}

/* Anexos de comentário */
let pendingAttachments = [];
function renderPendingFiles() {
  const el = $('comment-pending-files');
  if (!el) return;
  el.innerHTML = pendingAttachments.map((a, i) => {
    const preview = a.type.startsWith('image/')
      ? `<img src="${a.data}" class="pending-thumb">`
      : '<i data-lucide="file" class="ic-sm"></i>';
    return `<span class="pending-file">${preview} ${esc(a.name)} <button class="icon-btn danger" onclick="removePending(${i})" title="Remover"><i data-lucide="x" class="ic-sm"></i></button></span>`;
  }).join('');
}
function removePending(i) { pendingAttachments.splice(i, 1); renderPendingFiles(); }
function readFilesAsBase64(files, isImage) {
  [...files].forEach(file => {
    if (file.size > _maxUploadBytes()) { toast('Arquivo "' + file.name + '" excede ' + _maxUploadLabel() + ', o limite por arquivo do seu plano.', 'error'); return; }
    const reader = new FileReader();
    reader.onload = e => {
      if (isImage) {
        // Redimensiona imagens grandes
        const img = new Image();
        img.onload = () => {
          const max = 1200;
          let w = img.width, h = img.height;
          if (w > max || h > max) {
            const r = Math.min(max / w, max / h);
            w = Math.round(w * r); h = Math.round(h * r);
          }
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          canvas.getContext('2d').drawImage(img, 0, 0, w, h);
          const data = canvas.toDataURL('image/jpeg', 0.85);
          pendingAttachments.push({ name: file.name, type: file.type, data });
          renderPendingFiles();
        };
        img.src = e.target.result;
      } else {
        pendingAttachments.push({ name: file.name, type: file.type, data: e.target.result });
        renderPendingFiles();
      }
    };
    reader.readAsDataURL(file);
  });
}
function handleCommentFiles(ev) { readFilesAsBase64(ev.target.files, false); ev.target.value = ''; }
// Imagens agora entram INLINE no HTML do comentário (ao invés de virarem
// anexo separado). Reaproveita o pipeline de resize/JPEG do readImagesInline.
function handleCommentImages(ev) { readImagesInline(ev.target.files); ev.target.value = ''; }

/* ─── RICH EDITOR GENÉRICO ───
   Editor contenteditable + toolbar reutilizável (usado na descrição da
   demanda, na descrição padrão dos fluxos e no editor inline da demanda).
   Mesmo comportamento do editor de comentários. */
function isHtmlContent(s) {
  if (!s || typeof s !== 'string') return false;
  if (/<(p|div|br|ul|ol|li|strong|em|b|i|u|s|a|img|blockquote|span|h[1-6])\b[^>]*>/i.test(s)) return true;
  // Também trata entidades HTML como "já é HTML" — sem isso, uma string tipo
  // "&amp;&amp;" (que veio de um innerHTML) é achada plain-text e passa pelo
  // esc() de novo, virando "&amp;amp;&amp;amp;" (double-encoding do usuário).
  if (/&(?:amp|lt|gt|quot|nbsp|#\d+|#x[0-9a-f]+);/i.test(s)) return true;
  return false;
}
/* Renderiza o HTML de um rich editor. `id` é o id do contenteditable.
   `initial` pode ser markdown-legado ou HTML — detectado automaticamente. */
function renderRichEditor({ id, initial, placeholder, minHeight }) {
  const initialHtml = initial ? (isHtmlContent(initial) ? initial : mdRender(initial)) : '';
  const isEmpty = !initialHtml.trim();
  return `<div class="rich-editor-wrap">
    <div class="rich-toolbar">
      <button type="button" class="rich-tool" title="Negrito (Ctrl+B)" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','bold')"><i data-lucide="bold" class="ic-xs"></i></button>
      <button type="button" class="rich-tool" title="Itálico" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','italic')"><i data-lucide="italic" class="ic-xs"></i></button>
      <button type="button" class="rich-tool" title="Sublinhado" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','underline')"><i data-lucide="underline" class="ic-xs"></i></button>
      <button type="button" class="rich-tool" title="Tachado" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','strikeThrough')"><i data-lucide="strikethrough" class="ic-xs"></i></button>
      <span class="chat-tool-sep"></span>
      <button type="button" class="rich-tool" title="Lista numerada" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','insertOrderedList')"><i data-lucide="list-ordered" class="ic-xs"></i></button>
      <button type="button" class="rich-tool" title="Lista com marcadores" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','insertUnorderedList')"><i data-lucide="list" class="ic-xs"></i></button>
      <button type="button" class="rich-tool" title="Checklist" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','insertUnorderedList')"><i data-lucide="list-checks" class="ic-xs"></i></button>
      <span class="chat-tool-sep"></span>
      <button type="button" class="rich-tool" title="Citação" onmousedown="event.preventDefault()" onclick="execRichCmd('${id}','formatBlock','BLOCKQUOTE')"><i data-lucide="quote" class="ic-xs"></i></button>
      <span class="chat-tool-sep"></span>
      <input type="file" id="rich-img-input-${id}" accept="image/*" multiple style="display:none" onchange="handleRichImages(event, '${id}')">
      <button type="button" class="rich-tool" title="Imagem" onmousedown="event.preventDefault()" onclick="document.getElementById('rich-img-input-${id}').click()"><i data-lucide="image" class="ic-xs"></i></button>
    </div>
    <div class="rich-editor-input ${isEmpty ? 'is-empty' : ''}" id="${id}"
         contenteditable="true" role="textbox" aria-multiline="true"
         data-placeholder="${esc(placeholder || 'Escreva aqui…')}"
         ${minHeight ? `style="min-height:${minHeight}"` : ''}
         oninput="syncRichEmptyState(this)">${initialHtml}</div>
    ${editorResizeGrip(id)}
  </div>`;
}

/* Alça no canto inferior direito pra ajustar a altura do editor (só vertical) —
   pra ler um texto longo inteiro sem rolar dentro da caixa. Arrastar tira o
   limite de altura do CSS; duplo clique volta ao padrão. Vai logo depois do
   campo, num contêiner de altura zero, e se posiciona sobre o canto dele. */
function editorResizeGrip(targetId) {
  return `<div class="editor-resize-row"><button type="button" class="editor-resize-grip" data-resize-target="${targetId}"
    onmousedown="event.preventDefault()" title="Arraste para ajustar a altura · duplo clique volta ao padrão"
    aria-label="Ajustar altura do campo"><i data-lucide="grip-horizontal"></i></button></div>`;
}
document.addEventListener('pointerdown', e => {
  const grip = e.target.closest?.('.editor-resize-grip');
  const ed = grip && document.getElementById(grip.dataset.resizeTarget);
  if (!ed) return;
  e.preventDefault(); // não tira o foco do editor
  const startY = e.clientY;
  const startH = ed.getBoundingClientRect().height;
  const minH = parseFloat(getComputedStyle(ed).minHeight) || 40;
  ed.style.maxHeight = 'none';
  const move = ev => { ed.style.height = Math.max(minH, Math.round(startH + ev.clientY - startY)) + 'px'; };
  const up = () => {
    document.removeEventListener('pointermove', move);
    document.removeEventListener('pointerup', up);
  };
  document.addEventListener('pointermove', move);
  document.addEventListener('pointerup', up);
});
document.addEventListener('dblclick', e => {
  const grip = e.target.closest?.('.editor-resize-grip');
  const ed = grip && document.getElementById(grip.dataset.resizeTarget);
  if (ed) { ed.style.height = ''; ed.style.maxHeight = ''; }
});
/* Executa comando no editor específico (foca antes pra que a seleção
   corrente seja aplicada). */
function execRichCmd(editorId, cmd, value) {
  const el = document.getElementById(editorId);
  if (!el) return;
  el.focus();
  try { document.execCommand(cmd, false, value || null); } catch {}
  syncRichEmptyState(el);
}
/* Placeholder helper — mesma lógica do syncCommentEmptyState. */
function syncRichEmptyState(el) {
  if (!el) return;
  const hasImg = /<img\b/i.test(el.innerHTML || '');
  const hasText = (el.innerText || el.textContent || '').replace(/​/g, '').trim().length > 0;
  el.classList.toggle('is-empty', !hasImg && !hasText);
}
/* Handler de upload de imagem via input file (rich editor genérico). */
function handleRichImages(ev, editorId) {
  const el = document.getElementById(editorId);
  if (el && typeof _readImagesInlineInto === 'function') _readImagesInlineInto(el, ev.target.files);
  ev.target.value = '';
}
/* Getter/Setter que funciona tanto pra textarea antigo quanto contenteditable novo. */
function getRichValue(id) {
  const el = document.getElementById(id);
  if (!el) return '';
  if (el.tagName === 'TEXTAREA' || el.tagName === 'INPUT') return el.value || '';
  // Contenteditable — retorna HTML só se tiver conteúdo real.
  const html = el.innerHTML || '';
  const text = (el.innerText || '').replace(/​/g, '').trim();
  const hasImg = /<img\b/i.test(html);
  if (!text && !hasImg) return '';
  return html.trim();
}
function setRichValue(id, val) {
  const el = document.getElementById(id);
  if (!el) return;
  if (el.tagName === 'TEXTAREA' || el.tagName === 'INPUT') { el.value = val || ''; return; }
  const html = val ? (isHtmlContent(val) ? val : mdRender(val)) : '';
  el.innerHTML = html;
  syncRichEmptyState(el);
}
/* Monta um rich editor no lugar de um textarea existente. Preserva o id
   (agora aponta pro contenteditable), então getRichValue/setRichValue e
   qualquer código antigo que use $(id) continua funcionando. */
function mountRichEditor(id, opts) {
  const el = document.getElementById(id);
  if (!el) return;
  // Já montado? O id agora aponta pro contenteditable dentro do .rich-editor-wrap.
  // Sem esse check, chamadas subsequentes aninhavam wraps (toolbar duplicada).
  if (el.closest('.rich-editor-wrap')) return;
  const placeholder = opts?.placeholder || el.getAttribute('placeholder') || '';
  const minHeight = opts?.minHeight || '';
  const initial = el.value || '';
  const wrap = document.createElement('div');
  wrap.innerHTML = renderRichEditor({ id, initial, placeholder, minHeight });
  const built = wrap.firstElementChild;
  el.parentNode.replaceChild(built, el);
  if (typeof paintIcons === 'function') paintIcons();
}
/* ─── IMAGENS EM RICH TEXT ───
   Visualização: clique numa imagem de comentário/descrição renderizados abre o
   preview de anexos (zoom + baixar). Edição: clique numa imagem dentro de um
   editor mostra uma moldura com alça no canto — arrastar define a largura
   (atributo width em px, único formato que o sanitizer do server preserva). */
const RICH_IMG_VIEW_SELECTOR = '.chat-comment-text img, .comment-text img, .detail-description img, img.comment-img';
const RICH_IMG_MIN_WIDTH = 48;

function _richImageFile(img) {
  const src = img.currentSrc || img.src;
  const file = decodeURIComponent(String(src).split('?')[0].split('/').pop() || '');
  let ext = ((/\.([a-z0-9]{2,5})$/i.exec(file) || [])[1] || 'png').toLowerCase();
  if (ext === 'jpg') ext = 'jpeg';
  return { src, type: 'image/' + ext, name: img.getAttribute('alt') || `imagem.${ext === 'jpeg' ? 'jpg' : ext}` };
}
document.addEventListener('click', e => {
  const img = e.target.closest?.(RICH_IMG_VIEW_SELECTOR);
  if (!img || img.closest('[contenteditable="true"]')) return;
  e.preventDefault();
  const f = _richImageFile(img);
  openAttPreview(f.src, f.type, f.name);
});

let _imgResize = null; // { img, editor, frame }
function _placeImgResizer() {
  if (!_imgResize) return;
  const { img, frame } = _imgResize;
  if (!img.isConnected) { _hideImgResizer(); return; }
  const r = img.getBoundingClientRect();
  Object.assign(frame.style, { left: r.left + 'px', top: r.top + 'px', width: r.width + 'px', height: r.height + 'px' });
}
function _showImgResizer(img) {
  if (_imgResize?.img === img) return;
  _hideImgResizer();
  const frame = document.createElement('div');
  frame.className = 'img-resize-frame';
  frame.innerHTML = '<span class="img-resize-handle" title="Arraste para redimensionar · duplo clique volta ao tamanho original"></span>';
  document.body.appendChild(frame);
  _imgResize = { img, editor: img.closest('[contenteditable="true"]'), frame };
  _placeImgResizer();
  const handle = frame.querySelector('.img-resize-handle');
  handle.addEventListener('pointerdown', _startImgResize);
  handle.addEventListener('dblclick', () => { img.removeAttribute('width'); _commitImgResize(); });
  window.addEventListener('scroll', _placeImgResizer, true);
  window.addEventListener('resize', _placeImgResizer);
}
function _hideImgResizer() {
  if (!_imgResize) return;
  _imgResize.frame.remove();
  _imgResize = null;
  window.removeEventListener('scroll', _placeImgResizer, true);
  window.removeEventListener('resize', _placeImgResizer);
}
function _startImgResize(e) {
  e.preventDefault();
  e.stopPropagation();
  const { img, editor, frame } = _imgResize;
  const startX = e.clientX;
  const startW = img.getBoundingClientRect().width;
  const cs = getComputedStyle(editor);
  const maxW = editor.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
  frame.classList.add('is-dragging');
  const move = ev => {
    img.setAttribute('width', Math.round(Math.min(maxW, Math.max(RICH_IMG_MIN_WIDTH, startW + ev.clientX - startX))));
    _placeImgResizer();
  };
  const up = () => {
    frame.classList.remove('is-dragging');
    document.removeEventListener('pointermove', move);
    document.removeEventListener('pointerup', up);
    _commitImgResize();
  };
  document.addEventListener('pointermove', move);
  document.addEventListener('pointerup', up);
}
// Dispara `input` no editor: autosave da descrição e estado do compositor reagem igual a digitar.
function _commitImgResize() {
  const editor = _imgResize?.editor;
  _placeImgResizer();
  editor?.dispatchEvent(new Event('input', { bubbles: true }));
}
document.addEventListener('mousedown', e => {
  const img = e.target.closest?.('[contenteditable="true"] img');
  if (img) { _showImgResizer(img); return; }
  if (!e.target.closest?.('.img-resize-frame')) _hideImgResizer();
}, true);
// Digitar desloca a imagem (ou a apaga) — reposiciona/some a moldura junto.
document.addEventListener('input', () => { if (_imgResize) _placeImgResizer(); }, true);
document.addEventListener('keydown', e => { if (_imgResize && e.key === 'Escape') _hideImgResizer(); }, true);

// Redimensiona e comprime cada imagem, então injeta um <img src="data:..."> no
// caret do editor de comentário. Server converte data URIs em /uploads na hora
// de salvar. Suporta múltiplos arquivos numa chamada.
function readImagesInline(files) {
  const el = $('comment-input');
  if (!el || !el.isContentEditable) return;
  el.focus();
  [...files].forEach(file => {
    if (!file.type || !file.type.startsWith('image/')) return;
    if (file.size > 20 * 1024 * 1024) { toast('Imagem "' + file.name + '" excede 20 MB.', 'error'); return; }
    const reader = new FileReader();
    reader.onload = e => {
      const img = new Image();
      img.onload = () => {
        // 1920px + qualidade 0.9 — antes era 1200px @ 0.85 (screenshots ficavam
        // borrados/pequenos). Server aceita bem maior (25 MB/imagem, 60 MB/desc).
        const max = 1920;
        let w = img.width, h = img.height;
        if (w > max || h > max) { const r = Math.min(max / w, max / h); w = Math.round(w * r); h = Math.round(h * r); }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        const data = canvas.toDataURL('image/jpeg', 0.9);
        insertImageIntoEditor(el, data, file.name);
        draftSaveCommentCE(el);
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}
// Insere um <img> no caret atual do editor, ou no fim se o caret estiver fora.
function insertImageIntoEditor(el, dataUri, altName) {
  const imgHtml = `<img src="${dataUri}" alt="${esc(altName || '')}">`;
  const sel = window.getSelection && window.getSelection();
  if (sel && sel.rangeCount && el.contains(sel.anchorNode)) {
    try {
      document.execCommand('insertHTML', false, imgHtml + '<br>');
      return;
    } catch {}
  }
  // Fallback: append no fim.
  el.insertAdjacentHTML('beforeend', imgHtml + '<br>');
}

/* Paste (Ctrl+V) e drag-and-drop direto no compositor de comentário.
   Reaproveita readFilesAsBase64 → pendingAttachments → renderPendingFiles.
   stopPropagation evita conflito com o setupDragDrop do modal de demanda. */
function setupCommentComposer() {
  const ta = $('comment-input');
  const compose = ta?.closest('.comment-compose');
  if (!ta || !compose) return;

  ta.addEventListener('paste', e => {
    const items = e.clipboardData?.items || [];
    const imageFiles = [];
    for (const it of items) {
      if (it.kind === 'file' && it.type.startsWith('image/')) {
        const f = it.getAsFile();
        if (f) imageFiles.push(f);
      }
    }
    if (imageFiles.length) {
      e.preventDefault();
      readImagesInline(imageFiles);
      toast(imageFiles.length === 1 ? 'Imagem colada!' : `${imageFiles.length} imagens coladas!`);
      return;
    }
    // Cola texto: força texto puro pra não trazer estilos externos indesejados.
    if (ta.isContentEditable) {
      const txt = e.clipboardData?.getData('text/plain');
      if (txt !== undefined) {
        e.preventDefault();
        try { document.execCommand('insertText', false, txt); } catch {}
      }
    }
  });

  let dragDepth = 0;
  compose.addEventListener('dragenter', e => {
    if (!e.dataTransfer?.types?.includes('Files')) return;
    e.preventDefault();
    e.stopPropagation();
    dragDepth++;
    compose.classList.add('drag-over');
  });
  compose.addEventListener('dragover', e => {
    if (!e.dataTransfer?.types?.includes('Files')) return;
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = 'copy';
  });
  compose.addEventListener('dragleave', e => {
    if (!e.dataTransfer?.types?.includes('Files')) return;
    dragDepth = Math.max(0, dragDepth - 1);
    if (dragDepth === 0) compose.classList.remove('drag-over');
  });
  compose.addEventListener('drop', e => {
    e.preventDefault();
    e.stopPropagation();
    dragDepth = 0;
    compose.classList.remove('drag-over');
    const files = [...(e.dataTransfer?.files || [])];
    if (!files.length) return;
    const imgs = files.filter(f => f.type.startsWith('image/'));
    const others = files.filter(f => !f.type.startsWith('image/'));
    if (imgs.length) readImagesInline(imgs);           // imagens: inline no editor
    if (others.length) readFilesAsBase64(others, false); // outros: anexo separado
    const total = files.length;
    toast(`${total} arquivo${total === 1 ? '' : 's'} adicionado${total === 1 ? '' : 's'} ao comentário`);
  });
}

/* Edição de comentário */
function startEditComment(cid) {
  const d = demandById(detailId); if (!d) return;
  const c = d.comments.find(x => x.id === cid); if (!c) return;
  const el = document.getElementById('comment-' + cid);
  if (!el) return;
  // Marca globalmente que estamos editando — o compose principal fica bloqueado
  // pra evitar dois editores abertos ao mesmo tempo.
  _editingCommentId = cid;
  _updateComposeLock();
  const atts = (c.attachments || []).map((a, i) => {
    const preview = a.type && a.type.startsWith('image/') ? `<img src="${a.data}" class="pending-thumb">` : '<i data-lucide="file" class="ic-sm"></i>';
    return `<span class="pending-file">${preview} ${esc(a.name)} <button class="icon-btn danger" onclick="removeEditAtt('${cid}', ${i})" title="Remover"><i data-lucide="x" class="ic-sm"></i></button></span>`;
  }).join('');
  const startHtml = c.format === 'html'
    ? (c.text || '')
    : esc(c.text || '').replace(/\r?\n/g, '<br>');
  // Reusa o layout do chat-compose (mesmas classes) — evita "duas caixas
  // diferentes" e mantém consistência visual entre novo e editar.
  el.innerHTML = `
    <div class="chat-compose is-active chat-compose-editing" id="chat-compose-edit-${cid}">
      <div class="chat-compose-toolbar">
        <button type="button" class="chat-tool" title="Negrito" onmousedown="event.preventDefault()" onclick="execEditCommentCmd('${cid}','bold')"><i data-lucide="bold" class="ic-xs"></i></button>
        <button type="button" class="chat-tool" title="Itálico" onmousedown="event.preventDefault()" onclick="execEditCommentCmd('${cid}','italic')"><i data-lucide="italic" class="ic-xs"></i></button>
        <button type="button" class="chat-tool" title="Sublinhado" onmousedown="event.preventDefault()" onclick="execEditCommentCmd('${cid}','underline')"><i data-lucide="underline" class="ic-xs"></i></button>
        <button type="button" class="chat-tool" title="Tachado" onmousedown="event.preventDefault()" onclick="execEditCommentCmd('${cid}','strikeThrough')"><i data-lucide="strikethrough" class="ic-xs"></i></button>
        <span class="chat-tool-sep"></span>
        <button type="button" class="chat-tool" title="Lista numerada" onmousedown="event.preventDefault()" onclick="execEditCommentCmd('${cid}','insertOrderedList')"><i data-lucide="list-ordered" class="ic-xs"></i></button>
        <button type="button" class="chat-tool" title="Lista com marcadores" onmousedown="event.preventDefault()" onclick="execEditCommentCmd('${cid}','insertUnorderedList')"><i data-lucide="list" class="ic-xs"></i></button>
      </div>
      <div class="chat-compose-input comment-input comment-input-ce" id="edit-comment-text-${cid}"
           contenteditable="true" role="textbox" aria-multiline="true"
           oninput="syncCommentEmptyState(this)"
           onkeydown="if (event.key === 'Tab') event.preventDefault()"
           data-placeholder="Editar comentário…">${startHtml}</div>
      ${editorResizeGrip('edit-comment-text-' + cid)}
      <div class="comment-pending-files" id="edit-comment-files">${atts}</div>
      <div class="chat-compose-foot">
        <div class="chat-compose-foot-left">
          <input type="file" id="edit-file-input" multiple style="display:none" onchange="handleEditFiles(event,'${cid}')">
          <button class="chat-compose-icon" onclick="$('edit-file-input').click()" title="Anexar arquivo"><i data-lucide="paperclip" class="ic-xs"></i></button>
          <input type="file" id="edit-img-input" accept="image/*" multiple style="display:none" onchange="handleEditImagesInline(event,'${cid}')">
          <button class="chat-compose-icon" onclick="$('edit-img-input').click()" title="Imagem"><i data-lucide="image" class="ic-xs"></i></button>
        </div>
        <div class="chat-compose-foot-right">
          <button class="btn btn-ghost btn-sm" onclick="cancelEditComment('${cid}')">Cancelar</button>
          <button class="btn btn-confirm btn-sm" onclick="saveEditComment('${cid}')">Salvar</button>
        </div>
      </div>
    </div>`;
  el.dataset.editAtts = JSON.stringify(c.attachments || []);
  // Paste como texto puro + inline images (mesmo comportamento do compositor).
  const editEl = document.getElementById('edit-comment-text-' + cid);
  if (editEl) {
    editEl.addEventListener('paste', ev => {
      const items = ev.clipboardData?.items || [];
      const imgs = [];
      for (const it of items) if (it.kind === 'file' && it.type.startsWith('image/')) { const f = it.getAsFile(); if (f) imgs.push(f); }
      if (imgs.length) { ev.preventDefault(); _readImagesInlineInto(editEl, imgs); return; }
      const txt = ev.clipboardData?.getData('text/plain');
      if (txt !== undefined) { ev.preventDefault(); try { document.execCommand('insertText', false, txt); } catch {} }
    });
    editEl.focus();
    // Caret no fim.
    const range = document.createRange();
    range.selectNodeContents(editEl); range.collapse(false);
    const sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(range);
  }
}
function execEditCommentCmd(cid, cmd) {
  const el = document.getElementById('edit-comment-text-' + cid);
  if (!el) return;
  el.focus();
  try { document.execCommand(cmd, false, null); } catch {}
}
// Versão do readImagesInline que aceita um editor alvo — reaproveitada pelo
// editor de edição inline.
function _readImagesInlineInto(el, files) {
  el.focus();
  [...files].forEach(file => {
    if (!file.type || !file.type.startsWith('image/')) return;
    if (file.size > 20 * 1024 * 1024) { toast('Imagem "' + file.name + '" excede 20 MB.', 'error'); return; }
    const reader = new FileReader();
    reader.onload = e => {
      const img = new Image();
      img.onload = () => {
        // 1920px + qualidade 0.9 — antes era 1200px @ 0.85 (screenshots ficavam
        // borrados/pequenos). Server aceita bem maior (25 MB/imagem, 60 MB/desc).
        const max = 1920;
        let w = img.width, h = img.height;
        if (w > max || h > max) { const r = Math.min(max / w, max / h); w = Math.round(w * r); h = Math.round(h * r); }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        const data = canvas.toDataURL('image/jpeg', 0.9);
        insertImageIntoEditor(el, data, file.name);
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}
function handleEditImagesInline(ev, cid) {
  const el = document.getElementById('edit-comment-text-' + cid);
  if (el) _readImagesInlineInto(el, ev.target.files);
  ev.target.value = '';
}
function removeEditAtt(cid, idx) {
  const el = document.getElementById('comment-' + cid);
  const atts = JSON.parse(el.dataset.editAtts || '[]');
  atts.splice(idx, 1);
  el.dataset.editAtts = JSON.stringify(atts);
  const container = $('edit-comment-files');
  container.innerHTML = atts.map((a, i) => {
    const preview = a.type && a.type.startsWith('image/') ? `<img src="${a.data}" class="pending-thumb">` : '<i data-lucide="file" class="ic-sm"></i>';
    return `<span class="pending-file">${preview} ${esc(a.name)} <button class="icon-btn danger" onclick="removeEditAtt('${cid}', ${i})"><i data-lucide="x" class="ic-sm"></i></button></span>`;
  }).join('');
}
function handleEditFiles(ev, cid) {
  const el = document.getElementById('comment-' + cid);
  [...ev.target.files].forEach(file => {
    if (file.size > _maxUploadBytes()) { toast('"' + file.name + '" excede ' + _maxUploadLabel() + ', o limite por arquivo do seu plano.', 'error'); return; }
    const reader = new FileReader();
    reader.onload = e => {
      const atts = JSON.parse(el.dataset.editAtts || '[]');
      atts.push({ name: file.name, type: file.type, data: e.target.result });
      el.dataset.editAtts = JSON.stringify(atts);
      removeEditAtt(cid, -1); // re-render (splice -1 doesn't remove)
      // Actually re-render properly
      const container = $('edit-comment-files');
      container.innerHTML = atts.map((a, i) => {
        const preview = a.type && a.type.startsWith('image/') ? `<img src="${a.data}" class="pending-thumb">` : '<i data-lucide="file" class="ic-sm"></i>';
        return `<span class="pending-file">${preview} ${esc(a.name)} <button class="icon-btn danger" onclick="removeEditAtt('${cid}', ${i})"><i data-lucide="x" class="ic-sm"></i></button></span>`;
      }).join('');
    };
    reader.readAsDataURL(file);
  });
  ev.target.value = '';
}
async function saveEditComment(cid) {
  const el = document.getElementById('comment-' + cid);
  const editEl = document.getElementById('edit-comment-text-' + cid);
  const html = editEl ? _commentInputHtml(editEl) : '';
  const plain = editEl ? _commentInputPlain(editEl) : '';
  const attachments = JSON.parse(el.dataset.editAtts || '[]');
  const hasImg = /<img\b/i.test(html);
  if (!plain.trim() && !attachments.length && !hasImg) { toast('O comentário não pode ficar vazio.', 'error'); return; }
  try {
    const upd = await api('/demands/' + detailId + '/comment/' + cid, 'PUT', {
      text: html, format: 'html', attachments
    });
    patchDemand(upd);
    _editingCommentId = null;
    renderDetail();
    toast('Comentário atualizado!');
  } catch (e) { toast(e.message, 'error'); }
}
/* Cancela a edição inline de um comentário — recupera o compose principal. */
function cancelEditComment(cid) {
  _editingCommentId = null;
  renderDetail();
}
/* Controle global: quando um comentário está em edição, bloqueia o compose
   principal (evita duas caixas de escrita ao mesmo tempo). */
let _editingCommentId = null;
function _updateComposeLock() {
  const wrap = document.querySelector('.chat-compose-wrap');
  if (!wrap) return;
  if (_editingCommentId) wrap.classList.add('is-locked');
  else wrap.classList.remove('is-locked');
}

/* ─── PROJETOS ─── */
function renderProjects() {
  // Populate filters
  const allP = wsProjects();
  const clients = [...new Set(allP.map(p => p.client).filter(Boolean))].sort();
  const cSel = $('proj-f-client');
  const cPrev = cSel.value;
  cSel.innerHTML = '<option value="">Todos os clientes</option>' + clients.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join('');
  if ([...cSel.options].some(o => o.value === cPrev)) cSel.value = cPrev;

  applyFilterDropdown('proj-f-client');
  applyFilterDropdown('proj-f-status');

  // Apply filters
  const q = norm($('proj-search').value);
  const fc = $('proj-f-client').value;
  const fs = $('proj-f-status').value;
  let list = allP.filter(p => {
    if (q && !norm(p.name).includes(q) && !norm(p.client).includes(q)) return false;
    if (fc && p.client !== fc) return false;
    if (fs === 'active' && p.active === false) return false;
    if (fs === 'archived' && p.active !== false) return false;
    if (!fs && !showArchivedProjects && p.active === false) return false;
    return true;
  });

  // Sort
  list.sort((a, b) => {
    let va, vb;
    if (projSortKey === 'name') { va = a.name.toLowerCase(); vb = b.name.toLowerCase(); }
    else if (projSortKey === 'client') { va = (a.client || '').toLowerCase(); vb = (b.client || '').toLowerCase(); }
    else if (projSortKey === 'demands') { va = wsDemands().filter(d => d.projectId === a.id).length; vb = wsDemands().filter(d => d.projectId === b.id).length; }
    else if (projSortKey === 'flow') {
      const fa = wsFlows().find(f => f.projectId === a.id);
      const fb = wsFlows().find(f => f.projectId === b.id);
      va = norm(fa?.name || ''); vb = norm(fb?.name || '');
    }
    else if (projSortKey === 'status') { va = a.active !== false ? 0 : 1; vb = b.active !== false ? 0 : 1; }
    else { va = a.name; vb = b.name; }
    return va < vb ? -projSortDir : va > vb ? projSortDir : 0;
  });

  const archivedCount = allP.filter(p => p.active === false).length;
  $('proj-archive-toggle').textContent = showArchivedProjects ? 'Ocultar arquivados' : `Ver arquivados (${archivedCount})`;
  $('proj-archive-toggle').style.display = archivedCount || showArchivedProjects ? '' : 'none';

  $('projects-table-body').innerHTML = list.length ? list.map(p => {
    const count = wsDemands().filter(d => d.projectId === p.id).length;
    const exclusive = wsFlows().filter(f => f.projectId === p.id);
    const pAvatar = p.avatar
      ? `<img src="${p.avatar}" class="avatar" style="width:28px;height:28px;border-radius:6px">`
      : `<span class="avatar" style="width:28px;height:28px;font-size:11px;border-radius:6px;background:${hexDim(p.color)};color:${p.color}">${esc(p.name.charAt(0))}</span>`;
    // Admin e moderador têm ações completas. User comum não vê linha de ações.
    // Delete é restrito a admin+moderador (server também bloqueia via modOrAdmin).
    const canManageProject = !!(me.isAdmin || me.isModerator);
    const actions = canManageProject ? `
      <div class="row-actions">
        <button class="detail-icon-btn" title="Editar" onclick="openProjectModal('${p.id}')"><i data-lucide="pencil" class="ic-sm"></i></button>
        <button class="detail-icon-btn" title="Duplicar" onclick="duplicateProject('${p.id}')"><i data-lucide="copy" class="ic-sm"></i></button>
        ${p.active !== false ? `<button class="detail-icon-btn" title="Arquivar" onclick="archiveProject('${p.id}')"><i data-lucide="archive" class="ic-sm"></i></button>` : `<button class="detail-icon-btn" title="Restaurar" onclick="archiveProject('${p.id}')"><i data-lucide="archive-restore" class="ic-sm"></i></button>`}
        <button class="detail-icon-btn danger" title="Excluir" onclick="confirmDeleteProject('${p.id}')"><i data-lucide="trash-2" class="ic-sm"></i></button>
      </div>
    ` : '';
    return `<tr class="row-hover-actions" style="${p.active === false ? 'opacity:.55' : ''}">
      <td><div style="display:flex;align-items:center;gap:8px">${pAvatar}<span style="font-weight:600">${esc(p.name)}</span></div></td>
      <td>${esc(p.client || '—')}</td>
      <td>${exclusive.length ? exclusive.map(f => `<span class="pill pill-muted" style="font-size:10px">${esc(f.name)}</span>`).join(' ') : '<span style="color:var(--text-muted);font-size:12px">Fluxos gerais</span>'}</td>
      <td>${count}</td>
      <td>${p.active !== false ? '<span class="pill pill-success">Ativo</span>' : '<span class="pill pill-muted">Arquivado</span>'}</td>
      <td>${actions}</td>
    </tr>`;
  }).join('') : `<tr><td colspan="6">${emptyState('Nenhum projeto encontrado', 'Ajuste os filtros ou crie um novo projeto.', 'inbox')}</td></tr>`;
}
function sortProjects(key) {
  if (projSortKey === key) projSortDir *= -1;
  else { projSortKey = key; projSortDir = 1; }
  renderProjects();
}
function toggleArchivedProjects() {
  showArchivedProjects = !showArchivedProjects;
  $('proj-f-status').value = '';
  renderProjects();
}
async function archiveProject(id) {
  const p = projectById(id); if (!p) return;
  const action = p.active !== false ? 'Arquivar' : 'Restaurar';
  try {
    await api('/projects/' + id, 'PUT', { active: p.active === false });
    toast(p.active === false ? 'Projeto restaurado.' : 'Projeto arquivado.', 'warn');
    await refreshData();
  } catch (e) { toast(e.message, 'error'); }
}
async function confirmDeleteProject(id) {
  const p = projectById(id); if (!p) return;
  const linkedDemands = wsDemands().filter(d => d.projectId === id).length;
  const linkedFlows = wsFlows().filter(f => f.projectId === id).length;
  const ok = await showConfirm({
    title: 'Excluir projeto definitivamente',
    message: `Excluir <strong>${esc(p.name)}</strong> permanentemente?<br><br>${linkedDemands ? `Esta ação removerá também <strong>${linkedDemands}</strong> demanda(s) vinculada(s).<br>` : ''}${linkedFlows ? `${linkedFlows} fluxo(s) exclusivo(s) também serão removidos.<br>` : ''}<br><strong>Esta ação não pode ser desfeita.</strong>`,
    okLabel: 'Excluir definitivamente',
    danger: true
  });
  if (!ok) return;
  try {
    await api('/projects/' + id + '?force=1', 'DELETE');
    toastWithUndo('Projeto excluído (demandas incluídas).', () => api('/projects/' + id + '/undelete', 'POST'));
    await refreshData();
  } catch (e) { toast(e.message, 'error'); }
}
function removeProjectAvatar() {
  projAvatarData = null;
  refreshProjectAvatarPreview();
}
function handleProjectAvatar(ev) {
  const file = ev.target.files[0]; if (!file) return;
  const img = new Image();
  img.onload = () => {
    const s = 256;
    const canvas = document.createElement('canvas');
    canvas.width = s; canvas.height = s;
    const min = Math.min(img.width, img.height);
    const sx = (img.width - min) / 2, sy = (img.height - min) / 2;
    canvas.getContext('2d').drawImage(img, sx, sy, min, min, 0, 0, s, s);
    projAvatarData = canvas.toDataURL('image/jpeg', 0.85);
    refreshProjectAvatarPreview();
  };
  img.src = URL.createObjectURL(file);
  ev.target.value = '';
}
let projectModalClientId = null; // cliente associado nesta abertura do modal
async function openProjectModal(id, presetClientId) {
  editingProjectId = id || null;
  $('project-modal-title').textContent = id ? 'Editar Projeto' : 'Novo Projeto';
  const p = id ? projectById(id) : null;

  // Cliente obrigatório: vem do projeto em edição ou do preset (tela do cliente).
  // Sem qualquer contexto, redireciona pra Clientes em vez de abrir sem destino.
  projectModalClientId = p?.clientId || presetClientId || null;
  if (!projectModalClientId) {
    toast('Selecione um cliente pra adicionar um projeto.', 'warn');
    goPage('clients');
    return;
  }
  // Cliente do preset/projeto pode estar stale (frontend não sincronizado com backend).
  // Faz um refresh on-demand antes de abrir pra evitar erro "Cliente inválido" no save.
  if (!clientById(projectModalClientId)) {
    try { clients = await api('/clients'); } catch {}
    if (!clientById(projectModalClientId)) {
      toast('Cliente não encontrado. Selecione um cliente da lista.', 'error');
      projectModalClientId = null;
      goPage('clients');
      return;
    }
  }

  $('p-name').value = p?.name || '';
  setColorValue('p-color', p?.color || '#7A00FF');
  $('p-drive-files').value = p?.driveFiles || '';
  $('p-brand-assets').value = p?.brandAssets || '';
  $('p-guidelines').value = p?.guidelines || '';

  // Footer: edit mostra Excluir + toggle Estado; new esconde os dois.
  // Excluir restrito a admin/moderador — server também bloqueia via modOrAdmin.
  const canDeleteProject = !!(me.isAdmin || me.isModerator);
  $('p-delete-btn').style.display = (p && canDeleteProject) ? '' : 'none';
  $('p-status-group').style.display = p ? '' : 'none';
  projectModalStatusActive = p ? (p.active !== false) : true;
  refreshProjectStatusUI();

  projAvatarData = p?.avatar || null;
  refreshProjectAvatarPreview();

  openModal('project-modal');
  navPush(id ? (projectPath(id) + '/edit') : '/projects/new');
}

function refreshProjectAvatarPreview() {
  const el = $('p-avatar-preview');
  if (!el) return;
  if (projAvatarData) {
    el.style.backgroundImage = `url('${projAvatarData}')`;
    el.style.backgroundSize = 'cover';
    el.style.backgroundPosition = 'center';
    el.innerHTML = '';
    el.style.background = `url('${projAvatarData}') center/cover no-repeat`;
    el.classList.remove('is-empty');
    $('p-avatar-remove').style.display = '';
  } else {
    el.style.backgroundImage = '';
    el.style.background = '';
    el.classList.add('is-empty');
    el.innerHTML = '<i data-lucide="image" class="avatar-preview-icon"></i><span class="avatar-preview-hint">Sem foto</span>';
    if (window.lucide?.createIcons) lucide.createIcons();
    $('p-avatar-remove').style.display = 'none';
  }
}

